package com.freearcanes.slayergear;

import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumSet;
import java.util.List;
import java.util.Set;

final class GearStrategy
{
	private final String name;
	private final String location;
	private final String rationale;
	private final CombatStyle combatStyle;
	private final AttackType attackType;
	private final WeaponRule weaponRule;
	private final Set<TargetTrait> targetTraits;
	private final ElementalWeakness elementalWeakness;
	private final int elementalWeaknessPercent;
	private final int minimumMagic;
	private final int minimumRanged;
	private final String requiredWeapon;
	private final String requiredOffhand;
	private final List<String> preferredItems;
	private final double magicDefenceWeight;
	private final double prayerWeight;
	private final boolean ancientAoe;

	private GearStrategy(Builder builder)
	{
		this.name = builder.name;
		this.location = builder.location;
		this.rationale = builder.rationale;
		this.combatStyle = builder.combatStyle;
		this.attackType = builder.attackType;
		this.weaponRule = builder.weaponRule;
		this.targetTraits = Collections.unmodifiableSet(builder.targetTraits.isEmpty()
			? EnumSet.noneOf(TargetTrait.class) : EnumSet.copyOf(builder.targetTraits));
		this.elementalWeakness = builder.elementalWeakness;
		this.elementalWeaknessPercent = builder.elementalWeaknessPercent;
		this.minimumMagic = builder.minimumMagic;
		this.minimumRanged = builder.minimumRanged;
		this.requiredWeapon = builder.requiredWeapon;
		this.requiredOffhand = builder.requiredOffhand;
		this.preferredItems = Collections.unmodifiableList(new ArrayList<>(builder.preferredItems));
		this.magicDefenceWeight = builder.magicDefenceWeight;
		this.prayerWeight = builder.prayerWeight;
		this.ancientAoe = builder.ancientAoe;
	}

	static Builder builder()
	{
		return new Builder();
	}

	String getName() { return name; }
	String getLocation() { return location; }
	String getRationale() { return rationale; }
	CombatStyle getCombatStyle() { return combatStyle; }
	AttackType getAttackType() { return attackType; }
	WeaponRule getWeaponRule() { return weaponRule; }
	Set<TargetTrait> getTargetTraits() { return targetTraits; }
	ElementalWeakness getElementalWeakness() { return elementalWeakness; }
	int getElementalWeaknessPercent() { return elementalWeaknessPercent; }
	int getMinimumMagic() { return minimumMagic; }
	int getMinimumRanged() { return minimumRanged; }
	String getRequiredWeapon() { return requiredWeapon; }
	String getRequiredOffhand() { return requiredOffhand; }
	List<String> getPreferredItems() { return preferredItems; }
	double getMagicDefenceWeight() { return magicDefenceWeight; }
	double getPrayerWeight() { return prayerWeight; }
	boolean isAncientAoe() { return ancientAoe; }

	static final class Builder
	{
		private String name = "Slayer setup";
		private String location = "Task-dependent";
		private String rationale = "Best owned gear for this strategy.";
		private CombatStyle combatStyle = CombatStyle.MELEE;
		private AttackType attackType = AttackType.BALANCED;
		private WeaponRule weaponRule = WeaponRule.ANY;
		private final EnumSet<TargetTrait> targetTraits = EnumSet.noneOf(TargetTrait.class);
		private ElementalWeakness elementalWeakness = ElementalWeakness.NONE;
		private int elementalWeaknessPercent;
		private int minimumMagic = 1;
		private int minimumRanged = 1;
		private String requiredWeapon;
		private String requiredOffhand;
		private final List<String> preferredItems = new ArrayList<>();
		private double magicDefenceWeight = 0.08;
		private double prayerWeight = 1.2;
		private boolean ancientAoe;

		Builder name(String value) { this.name = value; return this; }
		Builder location(String value) { this.location = value; return this; }
		Builder rationale(String value) { this.rationale = value; return this; }
		Builder combatStyle(CombatStyle value) { this.combatStyle = value; return this; }
		Builder attackType(AttackType value) { this.attackType = value; return this; }
		Builder weaponRule(WeaponRule value) { this.weaponRule = value; return this; }
		Builder targetTrait(TargetTrait value) { if (value != null) targetTraits.add(value); return this; }
		Builder targetTraits(Iterable<TargetTrait> values) { if (values != null) for (TargetTrait value : values) if (value != null) targetTraits.add(value); return this; }
		Builder elementalWeakness(ElementalWeakness value, int percent)
		{
			this.elementalWeakness = value == null ? ElementalWeakness.NONE : value;
			this.elementalWeaknessPercent = Math.max(0, percent);
			return this;
		}
		Builder minimumMagic(int value) { this.minimumMagic = value; return this; }
		Builder minimumRanged(int value) { this.minimumRanged = value; return this; }
		Builder requiredWeapon(String value) { this.requiredWeapon = value; return this; }
		Builder requiredOffhand(String value) { this.requiredOffhand = value; return this; }
		Builder preferredItem(String value) { if (value != null) this.preferredItems.add(value); return this; }
		Builder magicDefenceWeight(double value) { this.magicDefenceWeight = value; return this; }
		Builder prayerWeight(double value) { this.prayerWeight = value; return this; }
		Builder ancientAoe(boolean value) { this.ancientAoe = value; return this; }
		GearStrategy build() { return new GearStrategy(this); }
	}
}

package com.freearcanes.slayergear;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.function.IntUnaryOperator;
import net.runelite.api.Item;

/**
 * Preserves the supply portion of a completed bank loadout while the player is
 * using that trip. The state is intentionally UI-free: opening a bank resets it.
 */
final class TripPreparationState
{
	private boolean active;
	private final Set<Integer> preparedSupplyIds = new HashSet<>();
	private Item[] preparedSupplyItems = new Item[0];

	void reset()
	{
		active = false;
		preparedSupplyIds.clear();
		preparedSupplyItems = new Item[0];
	}

	void arm(
		GearRecommendations recommendations,
		Item[] packedItems,
		IntUnaryOperator canonicalize)
	{
		reset();
		if (recommendations == null
			|| recommendations.getState() != GearRecommendations.State.READY
			|| !recommendations.getReadiness().isReadyToLeave())
		{
			return;
		}

		for (SupplyRecommendation supply : recommendations.getSupplies())
		{
			if (supply.isEnabledForTrip()
				&& supply.getCanonicalItemId() > 0
				&& supply.getStatus().isPacked()
				&& supply.hasRecommendedQuantityPacked())
			{
				preparedSupplyIds.add(supply.getCanonicalItemId());
			}
		}

		List<Item> snapshot = new ArrayList<>();
		if (packedItems != null)
		{
			for (Item item : packedItems)
			{
				if (isUsable(item)
					&& preparedSupplyIds.contains(canonicalize.applyAsInt(item.getId())))
				{
					snapshot.add(new Item(item.getId(), item.getQuantity()));
				}
			}
		}
		preparedSupplyItems = snapshot.toArray(new Item[0]);
		active = true;
	}

	Item[] suppliesForScoring(Item[] livePackedItems, IntUnaryOperator canonicalize)
	{
		if (!active || preparedSupplyIds.isEmpty())
		{
			return livePackedItems == null ? new Item[0] : livePackedItems;
		}

		List<Item> effective = new ArrayList<>();
		for (Item item : preparedSupplyItems)
		{
			effective.add(new Item(item.getId(), item.getQuantity()));
		}
		if (livePackedItems != null)
		{
			for (Item item : livePackedItems)
			{
				if (isUsable(item)
					&& !preparedSupplyIds.contains(canonicalize.applyAsInt(item.getId())))
				{
					effective.add(item);
				}
			}
		}
		return effective.toArray(new Item[0]);
	}

	boolean isActive()
	{
		return active;
	}

	static boolean assignmentChanged(
		String previousTask,
		String previousLocation,
		int previousAmount,
		String currentTask,
		String currentLocation,
		int currentAmount)
	{
		if (previousTask == null)
		{
			return false;
		}
		return !safe(previousTask).equals(safe(currentTask))
			|| !safe(previousLocation).equals(safe(currentLocation))
			|| currentAmount > previousAmount;
	}

	private static boolean isUsable(Item item)
	{
		return item != null && item.getId() > 0 && item.getQuantity() > 0;
	}

	private static String safe(String value)
	{
		return value == null ? "" : value.trim();
	}
}

package com.freearcanes.slayergear;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

class TaskPrepReminderOverlay extends Overlay
{
	private static final long DISPLAY_MILLIS = 6_500L;
	private static final long FADE_MILLIS = 1_200L;
	private static final int HEIGHT = 52;
	private static final int MIN_WIDTH = 285;
	private static final int MAX_WIDTH = 440;
	private static final Color GOLD = new Color(224, 174, 73);
	private static final Color TEXT = new Color(238, 232, 213);
	private static final Color BACKGROUND = new Color(24, 20, 14);

	private final SlayerGearAdvisorConfig config;
	private String title;
	private String message;
	private long expiresAt;

	@Inject
	TaskPrepReminderOverlay(SlayerGearAdvisorPlugin plugin, SlayerGearAdvisorConfig config)
	{
		super(plugin);
		this.config = config;
		setPosition(OverlayPosition.TOP_CENTER);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		setPriority(PRIORITY_HIGH);
		setMovable(false);
	}

	void show(GearRecommendations recommendations)
	{
		hide();
		if (!config.prepReminderEnabled() || recommendations == null
			|| recommendations.getState() != GearRecommendations.State.READY) return;

		ReadinessReport readiness = recommendations.getReadiness();
		List<String> reminders = new ArrayList<>();
		for (String critical : readiness.getMissingCritical())
		{
			reminders.add(critical);
			if (reminders.size() == 2) break;
		}
		if (reminders.isEmpty())
		{
			for (SupplyRecommendation supply : recommendations.getSupplies())
			{
				if (shouldRemindSupply(supply))
				{
					String quantity = "";
					if (supply.hasQuantityTarget())
					{
						quantity = "shots".equals(supply.getQuantityUnit())
							? supply.getQuantityStillNeeded() + " "
							: supply.getWithdrawalsStillNeeded() + "× ";
					}
					reminders.add(quantity + supply.getItemName());
					if (reminders.size() == 2) break;
				}
			}
		}
		if (reminders.isEmpty() && readiness.getGearPacked() < readiness.getGearTotal())
			reminders.add("Gear " + readiness.getGearPacked() + "/" + readiness.getGearTotal() + " packed");
		if (reminders.isEmpty()) return;

		title = readiness.isReadyToLeave() ? "Slayer prep suggestion" : "Slayer prep incomplete";
		message = (readiness.isReadyToLeave() ? "Consider: " : "Missing: ") + String.join("  •  ", reminders);
		expiresAt = System.currentTimeMillis() + DISPLAY_MILLIS;
	}

	void hide()
	{
		expiresAt = 0L;
		title = null;
		message = null;
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		long remaining = expiresAt - System.currentTimeMillis();
		if (remaining <= 0 || title == null || message == null)
		{
			return null;
		}

		float fade = remaining < FADE_MILLIS
			? Math.max(0f, remaining / (float) FADE_MILLIS)
			: 1f;

		graphics.setRenderingHint(
			RenderingHints.KEY_TEXT_ANTIALIASING,
			RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
		graphics.setFont(FontManager.getRunescapeSmallFont());
		FontMetrics bodyMetrics = graphics.getFontMetrics();
		graphics.setFont(FontManager.getRunescapeBoldFont());
		FontMetrics titleMetrics = graphics.getFontMetrics();
		int width = Math.max(
			MIN_WIDTH,
			Math.max(titleMetrics.stringWidth(title), bodyMetrics.stringWidth(message)) + 28);
		width = Math.min(MAX_WIDTH, width);

		graphics.setColor(withAlpha(BACKGROUND, (int) (222 * fade)));
		graphics.fillRoundRect(0, 0, width, HEIGHT, 8, 8);
		graphics.setColor(withAlpha(Color.BLACK, (int) (190 * fade)));
		graphics.drawRoundRect(1, 1, width - 3, HEIGHT - 3, 8, 8);
		graphics.setColor(withAlpha(GOLD, (int) (235 * fade)));
		graphics.drawRoundRect(0, 0, width - 1, HEIGHT - 1, 8, 8);
		graphics.fillRect(9, 7, 3, HEIGHT - 14);

		graphics.setFont(FontManager.getRunescapeBoldFont());
		graphics.setColor(withAlpha(Color.BLACK, (int) (230 * fade)));
		graphics.drawString(title, 19, 20);
		graphics.setColor(withAlpha(GOLD, (int) (255 * fade)));
		graphics.drawString(title, 18, 19);

		graphics.setFont(FontManager.getRunescapeSmallFont());
		graphics.setColor(withAlpha(Color.BLACK, (int) (230 * fade)));
		graphics.drawString(message, 19, 40);
		graphics.setColor(withAlpha(TEXT, (int) (255 * fade)));
		graphics.drawString(message, 18, 39);

		return new Dimension(width, HEIGHT);
	}

	static boolean shouldRemindSupply(SupplyRecommendation supply)
	{
		return supply != null
			&& supply.isEnabledForTrip()
			&& supply.getStatus().isBanked()
			&& (!supply.getStatus().isPacked() || !supply.hasRecommendedQuantityPacked())
			&& (supply.isRequired() || isPrepReminderSupply(supply));
	}

	private static boolean isPrepReminderSupply(SupplyRecommendation supply)
	{
		return "Goading".equals(supply.getCategory())
			|| "Prayer regen".equals(supply.getCategory());
	}

	private static Color withAlpha(Color color, int alpha)
	{
		return new Color(
			color.getRed(),
			color.getGreen(),
			color.getBlue(),
			Math.max(0, Math.min(255, alpha)));
	}
}

package com.freearcanes.slayergear;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import javax.inject.Inject;
import net.runelite.api.Item;

final class InventoryCapacityPlanner
{
	@Inject
	InventoryCapacityPlanner()
	{
	}

	GearRecommendations apply(
		GearRecommendations recommendations,
		Item[] inventoryItems,
		boolean bankPlanLocked,
		boolean bankRefreshPending)
	{
		if (recommendations == null
			|| recommendations.getState() != GearRecommendations.State.READY)
		{
			return recommendations;
		}

		List<SupplyRecommendation> supplies =
			new ArrayList<>(recommendations.getSupplies());
		int occupiedSlots = occupiedSlots(inventoryItems);
		int pendingGearSlots = pendingGearSlots(recommendations);
		int requestedSlots = occupiedSlots + pendingGearSlots + supplySlots(supplies);
		int excess = Math.max(0, requestedSlots - InventoryCapacityPlan.INVENTORY_CAPACITY);
		List<String> reductions = new ArrayList<>();

		List<Integer> trimOrder = new ArrayList<>();
		for (int index = 0; index < supplies.size(); index++)
		{
			SupplyRecommendation supply = supplies.get(index);
			if (!supply.isRequired()
				&& supply.isEnabledForTrip()
				&& supply.isQuantityAdjustable()
				&& additionalSlots(supply) > 0)
			{
				trimOrder.add(index);
			}
		}
		trimOrder.sort(Comparator
			.comparingInt((Integer index) -> trimPriority(supplies.get(index)))
			.thenComparingInt(Integer::intValue));

		for (int index : trimOrder)
		{
			if (excess <= 0)
			{
				break;
			}

			SupplyRecommendation supply = supplies.get(index);
			int currentSlots = additionalSlots(supply);
			int slotsToRemove = Math.min(excess, currentSlots);
			int reducedQuantity = quantityForAdditionalSlots(
				supply, currentSlots - slotsToRemove);
			if (reducedQuantity >= supply.getRecommendedQuantity())
			{
				continue;
			}

			int reduction = supply.getRecommendedQuantity() - reducedQuantity;
			SupplyRecommendation adjusted = supply.withCapacityQuantity(reducedQuantity);
			supplies.set(index, adjusted);
			int freed = currentSlots - additionalSlots(adjusted);
			excess -= freed;
			if (freed > 0)
			{
				reductions.add(supply.getCategory() + " -" + reduction
					+ (supply.getQuantityUnit().isEmpty()
						? "" : " " + supply.getQuantityUnit()));
			}
		}

		int plannedSlots = occupiedSlots + pendingGearSlots + supplySlots(supplies);
		InventoryCapacityPlan plan = InventoryCapacityPlan.available(
			occupiedSlots,
			pendingGearSlots,
			requestedSlots,
			plannedSlots,
			reductions);
		return recommendations.withPreparationState(
			supplies, plan, bankPlanLocked, bankRefreshPending);
	}

	static int occupiedSlots(Item[] items)
	{
		if (items == null)
		{
			return 0;
		}

		int occupied = 0;
		for (Item item : items)
		{
			if (item != null && item.getId() > 0 && item.getQuantity() > 0)
			{
				occupied++;
			}
		}
		return occupied;
	}

	static int additionalSlots(SupplyRecommendation supply)
	{
		if (supply == null || !supply.isEnabledForTrip())
		{
			return 0;
		}
		if (!supply.hasQuantityTarget())
		{
			return supply.getStatus().isPacked() ? 0 : 1;
		}

		int remaining = supply.getQuantityStillNeeded();
		if (remaining <= 0)
		{
			return 0;
		}
		if ("shots".equals(supply.getQuantityUnit()))
		{
			return supply.getPackedQuantity() > 0 ? 0 : 1;
		}
		if ("doses".equals(supply.getQuantityUnit()))
		{
			int doseSize = Math.max(1, supply.getUnitsPerWithdrawal());
			return (remaining + doseSize - 1) / doseSize;
		}
		return remaining;
	}

	private static int pendingGearSlots(GearRecommendations recommendations)
	{
		if (recommendations.getLoadoutTiers().isEmpty())
		{
			return 0;
		}

		int slots = 0;
		for (GearRecommendation recommendation
			: recommendations.getLoadoutTiers().get(0).getItems().values())
		{
			if (recommendation.isBanked() && !recommendation.isPacked())
			{
				slots++;
			}
		}
		return slots;
	}

	private static int supplySlots(List<SupplyRecommendation> supplies)
	{
		int slots = 0;
		for (SupplyRecommendation supply : supplies)
		{
			slots += additionalSlots(supply);
		}
		return slots;
	}

	private static int quantityForAdditionalSlots(
		SupplyRecommendation supply,
		int additionalSlots)
	{
		int safeSlots = Math.max(0, additionalSlots);
		int packed = supply.getPackedQuantity();
		if ("shots".equals(supply.getQuantityUnit()))
		{
			return safeSlots == 0 ? packed : supply.getRecommendedQuantity();
		}
		if ("doses".equals(supply.getQuantityUnit()))
		{
			return Math.min(
				supply.getRecommendedQuantity(),
				packed + safeSlots * Math.max(1, supply.getUnitsPerWithdrawal()));
		}
		return Math.min(supply.getRecommendedQuantity(), packed + safeSlots);
	}

	private static int trimPriority(SupplyRecommendation supply)
	{
		switch (supply.getCategory())
		{
			case "Food":
				return 0;
			case "Run energy":
				return 1;
			case "Goading":
				return 2;
			case "Prayer regen":
				return 3;
			case "Combat boost":
			case "Ranged boost":
			case "Magic boost":
				return 4;
			case "Prayer":
				return 5;
			case "Cannon ammo":
				return 6;
			default:
				return 7;
		}
	}
}

package com.freearcanes.slayergear;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

final class ReadinessReport
{
	private final int gearPacked;
	private final int gearTotal;
	private final boolean protectionReady;
	private final boolean weaponAmmoReady;
	private final String spellStatus;
	private final int suppliesPacked;
	private final int suppliesTotal;
	private final List<String> missingCritical;

	ReadinessReport(
		int gearPacked,
		int gearTotal,
		boolean protectionReady,
		boolean weaponAmmoReady,
		String spellStatus,
		int suppliesPacked,
		int suppliesTotal,
		List<String> missingCritical)
	{
		this.gearPacked = gearPacked;
		this.gearTotal = gearTotal;
		this.protectionReady = protectionReady;
		this.weaponAmmoReady = weaponAmmoReady;
		this.spellStatus = spellStatus == null ? "Not required" : spellStatus;
		this.suppliesPacked = suppliesPacked;
		this.suppliesTotal = suppliesTotal;
		this.missingCritical = Collections.unmodifiableList(new ArrayList<>(missingCritical));
	}

	static ReadinessReport empty()
	{
		return new ReadinessReport(0, 0, true, true, "Not required", 0, 0, Collections.emptyList());
	}

	int getGearPacked() { return gearPacked; }
	int getGearTotal() { return gearTotal; }
	boolean isProtectionReady() { return protectionReady; }
	boolean isWeaponAmmoReady() { return weaponAmmoReady; }
	String getSpellStatus() { return spellStatus; }
	int getSuppliesPacked() { return suppliesPacked; }
	int getSuppliesTotal() { return suppliesTotal; }
	List<String> getMissingCritical() { return missingCritical; }
	boolean isReadyToLeave()
	{
		return gearTotal > 0
			&& gearPacked >= gearTotal
			&& protectionReady
			&& weaponAmmoReady
			&& missingCritical.isEmpty();
	}

	ReadinessReport withSupplyProgress(List<SupplyRecommendation> supplies)
	{
		int packed = 0;
		int total = 0;
		if (supplies != null)
		{
			for (SupplyRecommendation supply : supplies)
			{
				if ("Cannon setup".equals(supply.getCategory())
					|| !supply.isEnabledForTrip())
				{
					continue;
				}
				total++;
				if (supply.getStatus().isPacked()
					&& supply.hasRecommendedQuantityPacked())
				{
					packed++;
				}
			}
		}
		return new ReadinessReport(
			gearPacked,
			gearTotal,
			protectionReady,
			weaponAmmoReady,
			spellStatus,
			packed,
			total,
			missingCritical);
	}
}

