import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.Stroke;
import javax.inject.Inject;
import net.runelite.api.widgets.WidgetItem;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.WidgetItemOverlay;

class BankRecommendationOverlay extends WidgetItemOverlay
{
	private final SlayerGearAdvisorPlugin plugin;
	private final SlayerGearAdvisorConfig config;
	private final ItemManager itemManager;
	private final TieredBankLayout tieredBankLayout;

	@Inject
	BankRecommendationOverlay(
		SlayerGearAdvisorPlugin plugin,
		SlayerGearAdvisorConfig config,
		ItemManager itemManager,
		TieredBankLayout tieredBankLayout)
	{
		this.plugin = plugin;
		this.config = config;
		this.itemManager = itemManager;
		this.tieredBankLayout = tieredBankLayout;
		showOnBank();
		setPriority(PRIORITY_HIGH);
	}

	@Override
	public void renderItemOverlay(Graphics2D graphics, int itemId, WidgetItem widgetItem)
	{
		if (itemId < 0 || itemManager.getItemComposition(itemId).getPlaceholderTemplateId() != -1)
		{
			return;
		}

		Rectangle bounds = widgetItem.getCanvasBounds();
		if (plugin.isBankFilterActive())
		{
			int tier = tieredBankLayout.tierFor(widgetItem.getWidget());
			String heading = tieredBankLayout.headingFor(widgetItem.getWidget());
			if (heading != null)
			{
				Color color = tier > 0 ? colorFor(tier) : new Color(255, 152, 31);
				renderHeading(graphics, bounds, heading, color, tier == 1 ? 4 : 8);
			}
			if (tier > 0)
			{
				renderTierHighlight(graphics, bounds, tier, colorFor(tier), false);
			}
			SupplyRecommendation supply = tieredBankLayout.supplyFor(widgetItem.getWidget());
			if (supply != null && supply.getWithdrawalsStillNeeded() > 0)
			{
				renderWithdrawalBadge(graphics, bounds, supply.getWithdrawalsStillNeeded());
			}
			return;
		}

		if (!plugin.isHighlightsActive())
		{
			return;
		}

		GearRecommendations recommendations = plugin.getRecommendations();
		if (recommendations.getState() != GearRecommendations.State.READY)
		{
			return;
		}

		int canonicalItemId = itemManager.canonicalize(itemId);
		GearRecommendation recommendation = recommendations.find(canonicalItemId);
		if (recommendation == null)
		{
			return;
		}

		renderTierHighlight(
			graphics,
			bounds,
			recommendation.getRank(),
			colorFor(recommendation.getRank()),
			true);
	}

	private static void renderTierHighlight(
		Graphics2D graphics,
		Rectangle bounds,
		int tier,
		Color color,
		boolean showBadge)
	{
		if (bounds == null || bounds.width <= 2 || bounds.height <= 2)
		{
			return;
		}

		Stroke oldStroke = graphics.getStroke();
		graphics.setRenderingHint(
			RenderingHints.KEY_ANTIALIASING,
			RenderingHints.VALUE_ANTIALIAS_ON);

		Color fill = new Color(color.getRed(), color.getGreen(), color.getBlue(), 34);
		Color border = new Color(color.getRed(), color.getGreen(), color.getBlue(), 215);
		graphics.setColor(fill);
		graphics.fillRoundRect(
			bounds.x + 1,
			bounds.y + 1,
			bounds.width - 2,
			bounds.height - 2,
			6,
			6);

		graphics.setStroke(new BasicStroke(tier == 1 ? 2f : 1.35f));
		graphics.setColor(border);
		graphics.drawRoundRect(
			bounds.x + 1,
			bounds.y + 1,
			bounds.width - 3,
			bounds.height - 3,
			6,
			6);

		graphics.setColor(new Color(color.getRed(), color.getGreen(), color.getBlue(), 235));
		graphics.fillRect(
			bounds.x + 3,
			bounds.y + bounds.height - 4,
			Math.max(1, bounds.width - 6),
			2);

		if (showBadge)
		{
			graphics.setFont(FontManager.getRunescapeSmallFont());
			String text = Integer.toString(tier);
			int x = bounds.x + 4;
			int y = bounds.y + 11;
			graphics.setColor(Color.BLACK);
			graphics.drawString(text, x + 1, y + 1);
			graphics.setColor(color);
			graphics.drawString(text, x, y);
		}

		graphics.setStroke(oldStroke);
	}

	private Color colorFor(int rank)
	{
		switch (rank)
		{
			case 1:
				return config.bestColor();
			case 2:
				return config.alternativeColor();
			default:
				return config.tierThreeColor();
		}
	}

	private static void renderWithdrawalBadge(Graphics2D graphics, Rectangle bounds, int withdrawals)
	{
		if (bounds == null || withdrawals <= 0) return;
		String text = "×" + withdrawals;
		graphics.setFont(FontManager.getRunescapeBoldFont());
		int width = graphics.getFontMetrics().stringWidth(text) + 6;
		int height = 14;
		int x = bounds.x + bounds.width - width;
		int y = bounds.y + 1;
		graphics.setColor(new Color(20, 17, 12, 225));
		graphics.fillRoundRect(x, y, width, height, 5, 5);
		graphics.setColor(new Color(255, 193, 7));
		graphics.drawRoundRect(x, y, width - 1, height - 1, 5, 5);
		graphics.drawString(text, x + 3, y + 11);
	}

	private static void renderHeading(
		Graphics2D graphics,
		Rectangle firstItemBounds,
		String text,
		Color color,
		int columns)
	{
		graphics.setFont(FontManager.getRunescapeSmallFont());
		graphics.setRenderingHint(
			RenderingHints.KEY_TEXT_ANTIALIASING,
			RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
		int x = firstItemBounds.x;
		int baseline = firstItemBounds.y - 6;
		graphics.setColor(Color.BLACK);
		graphics.drawString(text, x + 1, baseline + 1);
		graphics.setColor(color);
		graphics.drawString(text, x, baseline);
		graphics.drawLine(
			x,
			firstItemBounds.y - 3,
			x + Math.max(1, columns) * (36 + 12) - 12,
			firstItemBounds.y - 3);
	}
}

package com.freearcanes.slayergear;

import net.runelite.client.plugins.banktags.BankTagsService;

/**
 * Keeps an Inventory Setups bank tag active while Best-in-Bank owns the item
 * layout. The tag is reopened without its custom layout so Inventory Setups can
 * still observe setup switches and deselection without intercepting withdrawals.
 */
final class InventorySetupBankTagState
{
	private static final String INVENTORY_SETUP_TAG_PREFIX = "_invsetup_";

	private String leasedTag;
	private boolean restoreWithLayout;

	boolean hasActiveInventorySetup(BankTagsService bankTagsService)
	{
		String activeTag = bankTagsService.getActiveTag();
		return activeTag != null && activeTag.startsWith(INVENTORY_SETUP_TAG_PREFIX);
	}

	boolean captureActive(BankTagsService bankTagsService)
	{
		if (!hasActiveInventorySetup(bankTagsService))
		{
			return false;
		}

		String activeTag = bankTagsService.getActiveTag();
		boolean activeHasLayout = bankTagsService.getActiveLayout() != null;
		if (!activeTag.equals(leasedTag) || activeHasLayout)
		{
			// A different setup, or the same setup reopened by Inventory Setups,
			// supersedes the lease currently held by Best-in-Bank.
			leasedTag = activeTag;
			restoreWithLayout = activeHasLayout;
		}
		return true;
	}

	boolean activeNeedsNeutralizing(BankTagsService bankTagsService)
	{
		return captureActive(bankTagsService)
			&& bankTagsService.getActiveLayout() != null;
	}

	void neutralizeActive(BankTagsService bankTagsService)
	{
		if (!captureActive(bankTagsService))
		{
			return;
		}
		openWithoutLayout(bankTagsService);
	}

	void reopenNeutralized(BankTagsService bankTagsService)
	{
		if (leasedTag != null)
		{
			openWithoutLayout(bankTagsService);
		}
	}

	void updateLayoutPreference(boolean useLayouts)
	{
		if (leasedTag != null)
		{
			restoreWithLayout = useLayouts;
		}
	}

	boolean shouldRestore(BankTagsService bankTagsService)
	{
		captureActive(bankTagsService);
		return leasedTag != null
			&& leasedTag.equals(bankTagsService.getActiveTag());
	}

	void restore(BankTagsService bankTagsService, boolean restore)
	{
		if (leasedTag == null || !restore)
		{
			clear();
			return;
		}

		int options = BankTagsService.OPTION_ALLOW_MODIFICATIONS
			| BankTagsService.OPTION_HIDE_TAG_NAME;
		if (!restoreWithLayout)
		{
			options |= BankTagsService.OPTION_NO_LAYOUT;
		}

		String tag = leasedTag;
		clear();
		bankTagsService.openBankTag(tag, options);
	}

	private void openWithoutLayout(BankTagsService bankTagsService)
	{
		bankTagsService.openBankTag(
			leasedTag,
			BankTagsService.OPTION_ALLOW_MODIFICATIONS
				| BankTagsService.OPTION_HIDE_TAG_NAME
				| BankTagsService.OPTION_NO_LAYOUT);
	}

	void clear()
	{
		leasedTag = null;
		restoreWithLayout = false;
	}
}

package com.freearcanes.slayergear;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import net.runelite.api.EquipmentInventorySlot;

final class GearRequirement
{
	private final String label;
	private final List<Option> options;

	private GearRequirement(String label, List<Option> options)
	{
		this.label = label;
		this.options = Collections.unmodifiableList(new ArrayList<>(options));
	}

	static GearRequirement anyOf(String label, Option... options)
	{
		return new GearRequirement(label, Arrays.asList(options));
	}

	static Option option(EquipmentInventorySlot slot, String tokenExpression)
	{
		return new Option(slot, tokenExpression);
	}

	String getLabel() { return label; }
	List<Option> getOptions() { return options; }

	boolean isSatisfied(Map<EquipmentInventorySlot, GearRecommendation> selected)
	{
		for (Option option : options)
		{
			GearRecommendation recommendation = selected.get(option.slot);
			if (recommendation != null && option.matches(recommendation.getItemName()))
			{
				return true;
			}
		}
		return false;
	}

	boolean restricts(EquipmentInventorySlot slot)
	{
		int count = 0;
		for (Option option : options)
		{
			if (option.slot == slot)
			{
				count++;
			}
		}
		return count > 0 && options.stream().allMatch(option -> option.slot == slot);
	}

	boolean matchesForSlot(EquipmentInventorySlot slot, String itemName)
	{
		for (Option option : options)
		{
			if (option.slot == slot && option.matches(itemName))
			{
				return true;
			}
		}
		return false;
	}

	static final class Option
	{
		private final EquipmentInventorySlot slot;
		private final String tokenExpression;

		private Option(EquipmentInventorySlot slot, String tokenExpression)
		{
			this.slot = slot;
			this.tokenExpression = tokenExpression;
		}

		EquipmentInventorySlot getSlot() { return slot; }
		String getTokenExpression() { return tokenExpression; }
		boolean hasSameTokens(Option other)
		{
			return other != null
				&& NameMatcher.normalize(tokenExpression).equals(NameMatcher.normalize(other.tokenExpression));
		}
		boolean matches(String itemName) { return NameMatcher.matchesAnyToken(itemName, tokenExpression); }
	}
}

package com.freearcanes.slayergear;

import java.util.Collections;
import java.util.EnumMap;
import java.util.Map;
import net.runelite.api.EquipmentInventorySlot;

final class LoadoutTier
{
	private final int rank;
	private final Map<EquipmentInventorySlot, GearRecommendation> items;
	private final int guidePrice;
	private final int riskCapGp;

	LoadoutTier(int rank, Map<EquipmentInventorySlot, GearRecommendation> items)
	{
		this(rank, items, 0, 0);
	}

	LoadoutTier(
		int rank,
		Map<EquipmentInventorySlot, GearRecommendation> items,
		int guidePrice,
		int riskCapGp)
	{
		this.rank = rank;
		EnumMap<EquipmentInventorySlot, GearRecommendation> copy = new EnumMap<>(EquipmentInventorySlot.class);
		copy.putAll(items);
		this.items = Collections.unmodifiableMap(copy);
		this.guidePrice = Math.max(0, guidePrice);
		this.riskCapGp = Math.max(0, riskCapGp);
	}

	int getRank() { return rank; }
	Map<EquipmentInventorySlot, GearRecommendation> getItems() { return items; }
	GearRecommendation get(EquipmentInventorySlot slot) { return items.get(slot); }
	int getGuidePrice() { return guidePrice; }
	int getRiskCapGp() { return riskCapGp; }
}

