package com.freearcanes.slayergear;

import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.function.IntUnaryOperator;
import net.runelite.api.Item;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class TripPreparationStateTest
{
	private static final IntUnaryOperator POTION_CANONICALIZER =
		itemId -> itemId == 101 || itemId == 102 ? 100 : itemId;

	@Test
	public void consumedPreparedSupplyUsesBankCloseSnapshotWithoutDuplicatingLiveDose()
	{
		TripPreparationState state = new TripPreparationState();
		SupplyRecommendation potion = new SupplyRecommendation(
			100, 100, "Divine super combat potion(4)", "Combat boost", "Boost",
			SupplyStatus.PACKED, false, 8, 8, 40, "doses");
		state.arm(
			readyRecommendations(Collections.singletonList(potion)),
			new Item[] {new Item(101, 2), new Item(200, 1)},
			POTION_CANONICALIZER);

		Item[] effective = state.suppliesForScoring(
			new Item[] {new Item(102, 1), new Item(200, 1)},
			POTION_CANONICALIZER);

		assertTrue(state.isActive());
		assertEquals(2, effective.length);
		assertEquals(2, quantityFor(effective, 101));
		assertEquals(0, quantityFor(effective, 102));
		assertEquals(1, quantityFor(effective, 200));
	}

	@Test
	public void deployedCannonPartRemainsPreparedUntilReset()
	{
		TripPreparationState state = new TripPreparationState();
		SupplyRecommendation cannonBase = new SupplyRecommendation(
			300, 300, "Cannon base", "Cannon setup", "Required cannon part",
			SupplyStatus.PACKED, true);
		state.arm(
			readyRecommendations(Collections.singletonList(cannonBase)),
			new Item[] {new Item(300, 1)},
			itemId -> itemId);

		assertEquals(1, quantityFor(
			state.suppliesForScoring(new Item[0], itemId -> itemId), 300));

		state.reset();
		assertFalse(state.isActive());
		assertEquals(0, state.suppliesForScoring(new Item[0], itemId -> itemId).length);
	}

	@Test
	public void incompleteBankExitDoesNotArmTripAllowance()
	{
		TripPreparationState state = new TripPreparationState();
		SupplyRecommendation missing = new SupplyRecommendation(
			300, 300, "Cannon base", "Cannon setup", "Required cannon part",
			SupplyStatus.BANKED, true);
		GearRecommendations incomplete = GearRecommendations.ready(
			"Dagannoth",
			80,
			null,
			null,
			Collections.emptyList(),
			Collections.emptyMap(),
			Collections.emptyList(),
			Collections.singletonList(missing),
			new ReadinessReport(
				0, 1, true, true, "Not required", 0, 0,
				Collections.singletonList("Pack Cannon base")),
			1);

		state.arm(incomplete, new Item[] {new Item(300, 1)}, itemId -> itemId);

		assertFalse(state.isActive());
	}

	@Test
	public void onlyARealAssignmentResetClearsTripLifecycle()
	{
		assertFalse(TripPreparationState.assignmentChanged(
			"Dagannoth", "Island of Stone", 80,
			"Dagannoth", "Island of Stone", 79));
		assertTrue(TripPreparationState.assignmentChanged(
			"Dagannoth", "Island of Stone", 1,
			"Dagannoth", "Island of Stone", 140));
		assertTrue(TripPreparationState.assignmentChanged(
			"Dagannoth", "Island of Stone", 80,
			"Dagannoth", "Lighthouse", 80));
		assertTrue(TripPreparationState.assignmentChanged(
			"Dagannoth", "Island of Stone", 80,
			"Bloodveld", "Meiyerditch Laboratory", 80));
	}

	private static GearRecommendations readyRecommendations(
		List<SupplyRecommendation> supplies)
	{
		return GearRecommendations.ready(
			"Dagannoth",
			80,
			null,
			null,
			Collections.emptyList(),
			Collections.emptyMap(),
			Collections.emptyList(),
			supplies,
			new ReadinessReport(
				1, 1, true, true, "Not required",
				supplies.size(), supplies.size(), Collections.emptyList()),
			1);
	}

	private static int quantityFor(Item[] items, int itemId)
	{
		return Arrays.stream(items)
			.filter(item -> item.getId() == itemId)
			.mapToInt(Item::getQuantity)
			.sum();
	}
}

package com.freearcanes.slayergear;

import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class BankFlowStateTest
{
	@Test
	public void openFilterConfigRefreshAndCloseSequenceIsStable()
	{
		BankFlowState state = new BankFlowState();
		state.openBank();
		assertTrue(state.isBankOpen());
		assertTrue(state.beginFilterTransition());
		assertFalse(state.beginFilterTransition());

		state.activateFilter();
		state.completeFilterTransition();
		assertTrue(state.isFilterActive());

		assertTrue(state.queueBankViewRefresh());
		assertFalse(state.queueBankViewRefresh());
		state.completeBankViewRefresh();
		assertTrue(state.queueBankViewRefresh());

		state.closeBank();
		assertFalse(state.isBankOpen());
		assertFalse(state.isFilterActive());
		assertFalse(state.queueBankViewRefresh());
	}

	@Test
	public void withdrawalBurstQueuesOnlyOneRecalculation()
	{
		BankFlowState state = new BankFlowState();
		state.openBank();
		assertTrue(state.queueRecalculation());
		assertFalse(state.queueRecalculation());
		assertFalse(state.queueRecalculation());
		state.completeRecalculation();
		assertTrue(state.queueRecalculation());
	}

	@Test
	public void closingBankCancelsPendingBankWork()
	{
		BankFlowState state = new BankFlowState();
		state.openBank();
		state.beginFilterTransition();
		state.activateFilter();
		state.queueRecalculation();
		state.queueBankViewRefresh();

		state.closeBank();

		assertTrue(state.beginFilterTransition());
		assertTrue(state.queueRecalculation());
		assertFalse(state.queueBankViewRefresh());
	}

	@Test
	public void strategyCycleIsDebouncedAndSessionResetReleasesIt()
	{
		BankFlowState state = new BankFlowState();
		assertTrue(state.queueStrategyCycle());
		assertFalse(state.queueStrategyCycle());
		state.completeStrategyCycle();
		assertTrue(state.queueStrategyCycle());

		state.resetSession();
		assertTrue(state.queueStrategyCycle());
		assertFalse(state.isBankOpen());
		assertFalse(state.isFilterActive());
	}

	@Test
	public void filterCannotActivateWithoutAnOpenBank()
	{
		BankFlowState state = new BankFlowState();
		state.activateFilter();
		assertFalse(state.isFilterActive());
		assertFalse(state.queueBankViewRefresh());
	}

	@Test
	public void bankLoadoutLocksAndQueuesOneExplicitRefresh()
	{
		BankFlowState state = new BankFlowState();
		state.openBank();
		state.lockLoadout();
		assertTrue(state.isLoadoutLocked());
		assertFalse(state.isLoadoutRefreshPending());

		state.markLoadoutRefreshPending();
		assertTrue(state.isLoadoutRefreshPending());
		assertTrue(state.queueLoadoutRefresh());
		assertFalse(state.queueLoadoutRefresh());

		state.unlockLoadout();
		state.completeLoadoutRefresh();
		assertFalse(state.isLoadoutLocked());
		assertFalse(state.isLoadoutRefreshPending());
		assertTrue(state.queueLoadoutRefresh());
	}

	@Test
	public void closingBankClearsLockedPlanState()
	{
		BankFlowState state = new BankFlowState();
		state.openBank();
		state.lockLoadout();
		state.markLoadoutRefreshPending();

		state.closeBank();

		assertFalse(state.isLoadoutLocked());
		assertFalse(state.isLoadoutRefreshPending());
		assertFalse(state.queueLoadoutRefresh());
	}

	@Test
	public void inventorySetupNeutralizationIsDebouncedAndFilterScoped()
	{
		BankFlowState state = new BankFlowState();
		assertFalse(state.queueInventorySetupNeutralization());

		state.openBank();
		state.activateFilter();
		assertTrue(state.queueInventorySetupNeutralization());
		assertFalse(state.queueInventorySetupNeutralization());

		state.completeInventorySetupNeutralization();
		assertTrue(state.queueInventorySetupNeutralization());
		state.deactivateFilter();
		assertFalse(state.queueInventorySetupNeutralization());
	}
}

package com.freearcanes.slayergear;

import net.runelite.api.EquipmentInventorySlot;
import net.runelite.client.game.ItemEquipmentStats;
import org.junit.Test;

import static org.junit.Assert.assertTrue;

public class WeaponScoringRegressionTest
{
	@Test
	public void emberlightBeatsAbyssalWhipOnBlackDemonsInBothPriorities()
	{
		GearStrategy demon = TaskProfiles.find("Black demons").orElseThrow()
			.getStrategies().stream()
			.filter(s -> s.getCombatStyle() == CombatStyle.MELEE)
			.findFirst().orElseThrow();

		ItemEquipmentStats emberlight = melee(63, 70, 0, 13, 4);
		ItemEquipmentStats whip = melee(0, 82, 0, 82, 4);

		double balancedEmber = GearScorer.scoreStats(demon, "Emberlight",
			EquipmentInventorySlot.WEAPON, emberlight, GearPriority.BALANCED);
		double balancedWhip = GearScorer.scoreStats(demon, "Abyssal whip",
			EquipmentInventorySlot.WEAPON, whip, GearPriority.BALANCED);
		double prayerEmber = GearScorer.scoreStats(demon, "Emberlight",
			EquipmentInventorySlot.WEAPON, emberlight, GearPriority.PRAYER_FIRST);
		double prayerWhip = GearScorer.scoreStats(demon, "Abyssal whip",
			EquipmentInventorySlot.WEAPON, whip, GearPriority.PRAYER_FIRST);

		assertTrue("Emberlight must beat Abyssal whip on a demon", balancedEmber > balancedWhip);
		assertTrue("Prayer First must preserve combat-optimal weapon ordering", prayerEmber > prayerWhip);
	}

	@Test
	public void abyssalWhipBeatsEmberlightOffTarget()
	{
		GearStrategy ordinary = GearStrategy.builder()
			.name("Ordinary slash")
			.combatStyle(CombatStyle.MELEE)
			.attackType(AttackType.SLASH)
			.build();

		double ember = GearScorer.scoreStats(ordinary, "Emberlight",
			EquipmentInventorySlot.WEAPON, melee(63, 70, 0, 13, 4));
		double whip = GearScorer.scoreStats(ordinary, "Abyssal whip",
			EquipmentInventorySlot.WEAPON, melee(0, 82, 0, 82, 4));

		assertTrue("Demonbane must not be hard-forced off target", whip > ember);
	}

	@Test
	public void graniteHammerIsStrongOnGargoylesButStillDynamic()
	{
		GearStrategy gargoyle = TaskProfiles.find("Gargoyles").orElseThrow()
			.getStrategies().get(0);

		double granite = GearScorer.scoreStats(gargoyle, "Granite hammer",
			EquipmentInventorySlot.WEAPON, melee(0, 0, 57, 56, 4));
		double cudgel = GearScorer.scoreStats(gargoyle, "Abyssal cudgel",
			EquipmentInventorySlot.WEAPON, melee(0, 0, 65, 70, 4));
		double exceptional = GearScorer.scoreStats(gargoyle, "Exceptional crush weapon",
			EquipmentInventorySlot.WEAPON, melee(0, 0, 160, 160, 4));

		assertTrue("Granite hammer should beat a normal strong Crush alternative", granite > cudgel);
		assertTrue("Golembane must remain dynamic rather than hard-forced", exceptional > granite);
	}

	@Test
	public void dragonHunterLanceBeatsRapierProxyOnDragons()
	{
		GearStrategy dragon = GearStrategy.builder()
			.name("Dragonbane melee")
			.combatStyle(CombatStyle.MELEE)
			.attackType(AttackType.STAB)
			.weaponRule(WeaponRule.DRAGONBANE)
			.targetTrait(TargetTrait.DRAGON)
			.build();

		double lance = GearScorer.scoreStats(dragon, "Dragon hunter lance",
