package com.freearcanes.slayergear;

import java.util.HashSet;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

public class CatalogConsistencyTest
{
	@Test
	public void everyRegisteredAliasResolvesToItsOriginalProfile()
	{
		Map<String, SlayerTaskProfile> catalog = TaskProfiles.catalogSnapshot();
		assertFalse(catalog.isEmpty());
		assertEquals(TaskProfiles.profileCount(),
			catalog.values().stream().distinct().count());

		for (Map.Entry<String, SlayerTaskProfile> entry : catalog.entrySet())
		{
			SlayerTaskProfile resolved = TaskProfiles.find(entry.getKey()).orElseThrow();
			assertEquals("Alias changed profile: " + entry.getKey(),
				entry.getValue().getKey(), resolved.getKey());
		}
	}

	@Test
	public void everyCuratedProfileAndStrategyHasCompleteMetadata()
	{
		Set<SlayerTaskProfile> checked = new HashSet<>();
		for (SlayerTaskProfile profile : TaskProfiles.catalogSnapshot().values())
		{
			if (!checked.add(profile)) continue;
			assertText("profile key", profile.getKey(), profile.getDisplayName());
			assertText("display name", profile.getDisplayName(), profile.getKey());
			assertText("summary", profile.getSummary(), profile.getKey());
			assertText("protection advice", profile.getProtectionAdvice(), profile.getKey());
			assertFalse("No strategies for " + profile.getKey(), profile.getStrategies().isEmpty());

			Set<String> strategyNames = new HashSet<>();
			for (GearStrategy strategy : profile.getStrategies())
			{
				assertText("strategy name", strategy.getName(), profile.getKey());
				assertTrue("Duplicate strategy name in " + profile.getKey(),
					strategyNames.add(NameMatcher.normalize(strategy.getName())));
				assertText("location", strategy.getLocation(), profile.getKey() + "/" + strategy.getName());
				assertText("rationale", strategy.getRationale(), profile.getKey() + "/" + strategy.getName());
				assertNotNull("Missing combat style in " + profile.getKey(), strategy.getCombatStyle());
				assertNotNull("Missing attack type in " + profile.getKey(), strategy.getAttackType());
				assertNotNull("Missing weapon rule in " + profile.getKey(), strategy.getWeaponRule());

				if (strategy.isAncientAoe())
				{
					assertEquals("Ancient AoE must be Magic: " + profile.getKey(),
						CombatStyle.MAGIC, strategy.getCombatStyle());
					assertTrue("Ancient AoE level must be at least 62: " + profile.getKey(),
						strategy.getMinimumMagic() >= 62);
				}
				if (strategy.getElementalWeakness() == ElementalWeakness.NONE)
				{
					assertEquals("NONE weakness cannot have a percentage: " + profile.getKey(),
						0, strategy.getElementalWeaknessPercent());
				}
				else
				{
					assertTrue("Elemental weakness needs a percentage: " + profile.getKey(),
						strategy.getElementalWeaknessPercent() > 0);
				}
				if (strategy.getRequiredOffhand() != null)
				{
					assertFalse("Off-hand strategy cannot require a known two-handed weapon: " + profile.getKey(),
						containsTwoHandedToken(strategy.getRequiredWeapon()));
				}
			}
		}
	}

	@Test
	public void everyCannonAliasHasMetadataAndHonorsNoCannonLocations()
	{
		Map<String, CannonTaskCatalog.CannonRoute> routes = CannonTaskCatalog.routesSnapshot();
		assertFalse(routes.isEmpty());
		assertEquals(CannonTaskCatalog.routeCount(),
			routes.values().stream().distinct().count());

		for (Map.Entry<String, CannonTaskCatalog.CannonRoute> entry : routes.entrySet())
		{
			CannonTaskCatalog.CannonRoute route = entry.getValue();
			assertText("cannon display name", route.getDisplayName(), entry.getKey());
			assertText("cannon location", route.getLocation(), entry.getKey());
			assertText("cannon rationale", route.getRationale(), entry.getKey());
			assertNotNull(route.getCombatStyle());
			assertNotNull(route.getAttackType());
			assertTrue("Alias does not resolve to its route: " + entry.getKey(),
				CannonTaskCatalog.find(entry.getKey()).isPresent());
			assertFalse("No-cannon location leaked route for " + entry.getKey(),
				CannonTaskCatalog.find(entry.getKey(), "Catacombs of Kourend").isPresent());
		}
	}

	@Test
	public void everySlayerMasterAssignmentHasCombatClassification()
	{
		Map<String, WeaponRule> rules = TaskCombatCatalog.weaponRulesSnapshot();
		for (Map.Entry<String, java.util.List<String>> master :
			SlayerMasterCatalog.allAssignments().entrySet())
		{
			for (String task : master.getValue())
			{
				assertTrue(master.getKey() + " task lacks combat classification: " + task,
					rules.containsKey(normalize(task)));
			}
		}
	}

	@Test
	public void specializedWeaponRulesReachResolvedStrategies()
	{
		for (Map.Entry<String, WeaponRule> entry : TaskCombatCatalog.weaponRulesSnapshot().entrySet())
		{
			if (entry.getValue() == WeaponRule.ANY) continue;
			SlayerTaskProfile profile = TaskProfiles.find(entry.getKey()).orElseThrow();
			assertTrue("Weapon rule " + entry.getValue() + " not applied to " + entry.getKey(),
				profile.getStrategies().stream()
					.anyMatch(strategy -> strategy.getWeaponRule() == entry.getValue()));
		}
	}

	@Test
	public void sharedAliasCatalogMakesCollisionPolicyExplicit()
	{
		AliasCatalog<String> catalog = new AliasCatalog<>(
			value -> value.trim().toLowerCase(Locale.ENGLISH));
		catalog.register("specific", AliasCatalog.CollisionPolicy.KEEP_FIRST, "Example");
		catalog.register("broad fallback", AliasCatalog.CollisionPolicy.KEEP_FIRST, "example");
		assertEquals("specific", catalog.get("EXAMPLE"));
		assertTrue(catalog.ignoredCollisionsSnapshot().containsKey("example"));

		catalog.register("refined", AliasCatalog.CollisionPolicy.REPLACE, "example");
		assertEquals("refined", catalog.get("Example"));
	}

	@Test
	public void broadBossAliasesCannotReplaceCuratedTaskProfiles()
	{
		assertEquals("hellhounds", TaskProfiles.find("Cerberus").orElseThrow().getKey());
		assertTrue("Expected the ignored broad Cerberus alias to be auditable",
			TaskProfiles.ignoredAliasCollisions().containsKey("cerberus"));
	}

	private static void assertText(String field, String value, String context)
	{
		assertNotNull("Missing " + field + ": " + context, value);
		assertFalse("Blank " + field + ": " + context, value.trim().isEmpty());
	}

	private static boolean containsTwoHandedToken(String requiredWeapon)
	{
		if (requiredWeapon == null) return false;
		String normalized = NameMatcher.normalize(requiredWeapon);
		return normalized.contains("bow")
			|| normalized.contains("halberd")
			|| normalized.contains("godsword")
			|| normalized.contains("maul")
			|| normalized.contains("bulwark");
	}

	private static String normalize(String value)
	{
		String normalized = value.trim().toLowerCase(Locale.ENGLISH)
			.replaceAll("[^a-z0-9]+", " ").trim();
		return normalized.startsWith("the ") ? normalized.substring(4) : normalized;
	}
}

package com.github.diogogdias.bisfinder.engine;

import com.github.diogogdias.bisfinder.calc.Constants;
import com.github.diogogdias.bisfinder.calc.dist.CalcMath;
import com.github.diogogdias.bisfinder.calc.model.Monster;
import com.github.diogogdias.bisfinder.calc.model.MonsterAttribute;
import com.github.diogogdias.bisfinder.calc.model.MonsterInputs;

/**
 * Chambers of Xeric party-size and Challenge-Mode scaling of the target's defence, from the public wiki
 * formulas. Only defensive stats affect our DPS (the monster's offence and HP do not), so only Defence -
 * and Magic where the monster defends with it - are scaled. Party member levels default to maxed (99 hp /
 * 126 combat), the common endgame case, so only party size and Challenge Mode come from the user.
 *
 * <p>Olm's defence is the same multi formula (its specials only touch HP and offence). Tombs of Amascut
 * invocation scaling is applied separately, at roll time, inside {@link DpsEngine}.
 *
 * <p>Not verified against an oracle (the ported engine was removed); spot-check against dps.osrs.wiki.
 */
public final class RaidScaling
{
	private static final int CM_PERCENT = 50;

	private RaidScaling()
	{
	}

	/** Returns the target with its defensive stats scaled for the Chambers of Xeric inputs, or unchanged. */
	public static Monster scaleCox(Monster monster)
	{
		if (monster == null || !monster.getAttributes().contains(MonsterAttribute.XERICIAN))
		{
			return monster;
		}

		Monster.Skills skills = monster.getSkills();
		boolean magicDefensive = Constants.COX_MAGIC_IS_DEFENSIVE_IDS.contains(monster.getId());

		// Skills sitting at 1 stay at 1; the remaining defensive skills are "linked" and share one base.
		boolean scaleDef = skills.getDef() != 1;
		boolean scaleMagic = magicDefensive && skills.getMagic() != 1;
		if (!scaleDef && !scaleMagic)
		{
			return monster;
		}
		int baseDefensive = Math.max(scaleDef ? skills.getDef() : 1, scaleMagic ? skills.getMagic() : 1);

		int scaled = Constants.COX_USE_SINGLES_SCALING_IDS.contains(monster.getId())
			? singlesDefence(monster, baseDefensive)
			: multiDefence(monster, baseDefensive);

		Monster.Skills updated = new Monster.Skills(
			skills.getAtk(),
			scaleDef ? scaled : skills.getDef(),
			skills.getHp(),
			scaleMagic ? scaled : skills.getMagic(),
			skills.getRanged(),
			skills.getStr());
		return monster.toBuilder().skills(updated).build();
	}

	/** Group scaling (most of the raid, including Olm): party-member levels, then party size, then CM. */
	private static int multiDefence(Monster monster, int baseDefensive)
	{
		MonsterInputs inputs = monster.getInputs();
		int partySize = clamp(inputs.getPartySize(), 1, 100);
		int partySizeM1 = partySize - 1;
		int highestHp = clamp(55 + CalcMath.trunc(44.0 * inputs.getPartyMaxHpLevel() / 99), 55, 99);

		int defensive = CalcMath.trunc((double) baseDefensive * highestHp / 99);
		int scalePct = 100 + CalcMath.iSqrt(partySizeM1) + CalcMath.trunc((double) partySizeM1 * 7 / 10);
		defensive = CalcMath.trunc((double) defensive * scalePct / 100);

		if (inputs.isFromCoxCm())
		{
			// Tekton's defence is bumped less than the flat +50%, more so in small parties.
			defensive = Constants.TEKTON_IDS.contains(monster.getId())
				? CalcMath.addPercent(defensive, partySize < 4 ? 20 : 35)
				: CalcMath.addPercent(defensive, CM_PERCENT);
		}
		return clamp(defensive, 50, 20_000);
	}

	/** Solo-intended monsters (scavenger beasts, vespine soldiers) scale off party levels only. */
	private static int singlesDefence(Monster monster, int baseDefensive)
	{
		MonsterInputs inputs = monster.getInputs();
		int statScaler = clamp(inputs.getPartyMaxHpLevel(), 55, 99);
		if (inputs.isFromCoxCm())
		{
			statScaler = CalcMath.addPercent(statScaler, CM_PERCENT);
		}
		return Math.max(CalcMath.trunc((double) baseDefensive * statScaler / 99), 1);
	}

	private static int clamp(int value, int min, int max)
	{
		return Math.max(min, Math.min(max, value));
	}
}

package com.github.diogogdias.bisfinder.engine;

/**
 * One hitsplat of an attack: the chance it lands and the damage range it rolls. A standard hit rolls
 * uniformly over {@code 0..maxHit}; weirdgloop's expected damage per landed hit for that is
 * {@code maxHit/2 + 1/(maxHit+1)}. A hit with a minimum (some effects guarantee a floor) instead rolls
 * uniformly over {@code minHit..maxHit}, whose mean is {@code (minHit + maxHit)/2}.
 *
 * <p>Expected value is linear, so an attack's expected damage is the sum of its hitsplats' — which is all
 * DPS needs, with no full probability mass to convolve.
 */
public final class Hitsplat
{
	private final double accuracy;
	private final int minHit;
	private final int maxHit;

	public Hitsplat(double accuracy, int minHit, int maxHit)
	{
		this.accuracy = accuracy;
		this.minHit = minHit;
		this.maxHit = maxHit;
	}

	/** A standard hitsplat with no minimum. */
	public static Hitsplat standard(double accuracy, int maxHit)
	{
		return new Hitsplat(accuracy, 0, maxHit);
	}

	public double expectedDamage()
	{
		if (maxHit <= 0 || accuracy <= 0.0)
		{
			return 0.0;
		}
		double meanGivenHit = minHit > 0
			? (minHit + maxHit) / 2.0
			: maxHit / 2.0 + 1.0 / (maxHit + 1.0);
		return accuracy * meanGivenHit;
	}

	public double getAccuracy()
	{
		return accuracy;
	}

	public int getMaxHit()
	{
		return maxHit;
	}
}

package com.github.diogogdias.bisfinder.engine;

/**
 * Ranged max hit and hit chance, from the OSRS Wiki DPS formulas
 * (https://oldschool.runescape.wiki/w/Damage_per_second/Ranged). The effective-level and roll maths are
 * the same shape as melee; the inputs are the ranged strength/attack bonuses and the monster's ranged
 * defence for the ammo's damage type (standard / light / heavy).
 */
public final class RangedCalc
{
	private static final int NPC_EFFECTIVE_DEFENCE_BONUS = 9;

	/** Regular void ranging: +10% ranged attack and strength, rounded down. */
	private static final Factor VOID_RANGED = new Factor(11, 10);

	private RangedCalc()
	{
	}

	public static int effectiveLevel(int rangedLevel, int boost, Factor prayer, int stanceBonus, boolean voidBonus)
	{
		int current = rangedLevel + boost;
		int effective = prayer.applyFloor(current) + stanceBonus + 8;
		if (voidBonus)
		{
			effective = VOID_RANGED.applyFloor(effective);
		}
		return effective;
	}

	public static int maxHit(int effectiveRangedStrength, int rangedStrengthBonus)
	{
		return RollMath.maxHitFromEffective(effectiveRangedStrength, rangedStrengthBonus);
	}

	public static double hitChance(int effectiveRangedAttack, int rangedAttackBonus,
		int monsterDefenceLevel, int monsterRangedDefenceBonus)
	{
		long attackRoll = RollMath.attackRoll(effectiveRangedAttack, rangedAttackBonus);
		long defenceRoll = RollMath.defenceRoll(monsterDefenceLevel + NPC_EFFECTIVE_DEFENCE_BONUS,
			monsterRangedDefenceBonus);
		return RollMath.normalAccuracy(attackRoll, defenceRoll);
	}
}

package com.github.diogogdias.bisfinder.engine;

import java.util.Arrays;
import java.util.Collections;
import java.util.List;

/**
 * An attack's hitsplats. Most weapons are a single standard hitsplat; multi-hit weapons (Scythe of vitur,
 * dual-hit crossbows, ...) and proc effects contribute additional hitsplats. DPS is the summed expected
 * damage over the weapon's attack speed.
 */
public final class AttackDistribution
{
	private final List<Hitsplat> hitsplats;

	public AttackDistribution(List<Hitsplat> hitsplats)
	{
		this.hitsplats = Collections.unmodifiableList(hitsplats);
	}

	public static AttackDistribution single(Hitsplat hitsplat)
	{
		return new AttackDistribution(Collections.singletonList(hitsplat));
	}

	public static AttackDistribution of(Hitsplat... hitsplats)
	{
		return new AttackDistribution(Arrays.asList(hitsplats));
	}

	public double expectedDamage()
	{
		double total = 0.0;
		for (Hitsplat hitsplat : hitsplats)
		{
			total += hitsplat.expectedDamage();
		}
		return total;
	}

	public double dps(int attackSpeedTicks)
	{
		return expectedDamage() / (attackSpeedTicks * RollMath.SECONDS_PER_TICK);
	}

	public List<Hitsplat> getHitsplats()
	{
		return hitsplats;
	}
}

package com.github.diogogdias.bisfinder.engine;

/**
 * Magic max hit and hit chance, from the OSRS Wiki DPS formulas
 * (https://oldschool.runescape.wiki/w/Damage_per_second/Magic and /Maximum_magic_hit).
 *
 * <p>Two things differ from melee/ranged: the effective level adds 9 (not 8) and applies the magic void
 * multiplier of 1.45; and the monster's defence roll uses its Magic level, not its Defence level. Magic
 * max hit does not use the effective level at all for standard spells — it scales the spell's base max by
 * the summed magic-damage bonus (gear + prayer + void), each in thousandths.
 *
 * <p>Only the standard multiplier is modelled here. Shadow, salve, elemental weakness, slayer, tomes and
 * the other conditional multipliers are layered on separately.
 */
public final class MagicCalc
{
	private static final int NPC_EFFECTIVE_DEFENCE_BONUS = 9;

	/** Magic void raises the effective magic level (accuracy) by 45%, rounded down. */
	private static final Factor VOID_MAGIC = new Factor(145, 100);

	private MagicCalc()
	{
	}

	/**
	 * {@code floor(floor((magic + boost) * prayer) * void) + stanceBonus + 9}. The stance bonus is only
	 * non-zero on powered staves (+3 Accurate, +1 Longrange).
	 */
	public static int effectiveLevel(int magicLevel, int boost, Factor prayer, int stanceBonus, boolean voidMagic)
	{
		int effective = prayer.applyFloor(magicLevel + boost);
		if (voidMagic)
		{
			effective = VOID_MAGIC.applyFloor(effective);
		}
		return effective + stanceBonus + 9;
	}

	/**
	 * {@code floor(baseSpellMax * (1 + magicDamageThousandths / 1000))}, where the bonus is the sum of the
	 * gear magic-strength, the prayer's magic-damage bonus and any (elite) void magic damage.
	 */
	public static int maxHit(int baseSpellMax, int magicDamageThousandths)
	{
		return (int) Math.floor(baseSpellMax * (1.0 + magicDamageThousandths / 1000.0));
	}

	public static double hitChance(int effectiveMagic, int magicAttackBonus,
		int monsterMagicLevel, int monsterMagicDefenceBonus)
	{
		long attackRoll = RollMath.attackRoll(effectiveMagic, magicAttackBonus);
		long defenceRoll = RollMath.defenceRoll(monsterMagicLevel + NPC_EFFECTIVE_DEFENCE_BONUS,
			monsterMagicDefenceBonus);
		return RollMath.normalAccuracy(attackRoll, defenceRoll);
	}
}

package com.github.diogogdias.bisfinder.engine;

/**
 * The shared, game-defined combat rolls: effective levels, max hit, attack/defence rolls and the standard
 * accuracy formula. These are dictated by the game's own maths — there is only one correct way to write
 * them — and are documented on the OSRS Wiki (Damage per second/Melee, /Ranged, /Magic).
 *
 * <p>The roll and accuracy expressions here follow the {@code best-dps} RuneLite plugin, which is
 * BSD-2-Clause licensed:
 * <pre>
 *   Copyright (c) 2026, guccifurs (best-dps). All rights reserved.
 *   Redistributed under the BSD 2-Clause License; see NOTICE.md.
 * </pre>
 *
 * <p>This class deliberately contains no higher-level modelling (hit distributions, procs, specs): those
 * are built separately from the public wiki formulas.
 */
public final class RollMath
{
	public static final double SECONDS_PER_TICK = 0.6;

	private RollMath()
	{
	}

	/** {@code floor(level * prayerMultiplier) + stanceBonus + 8}. */
	public static int effectiveLevel(int level, double prayerMultiplier, int stanceBonus)
	{
		return (int) Math.floor(level * prayerMultiplier) + stanceBonus + 8;
	}

	/** Standard max hit: {@code floor((effStr * (strengthBonus + 64) + 320) / 640)}. */
	public static int maxHitFromEffective(int effectiveStrength, int strengthBonus)
	{
		return Math.max(0, (int) Math.floor((effectiveStrength * (strengthBonus + 64.0) + 320.0) / 640.0));
	}

	/**
	 * Osmumten's fang accuracy: it rolls the hit twice and keeps the better, giving a higher effective
	 * chance to land than a normal attack. Formula from the {@code best-dps} BSD-2 plugin.
	 */
	public static double fangAccuracy(long attackRoll, long defenceRoll)
	{
		double atk = attackRoll;
		double def = defenceRoll;
		if (atk < 0)
		{
			atk = Math.min(0, atk + 2);
		}
		if (def < 0)
		{
			def = Math.min(0, def + 2);
		}
		if (atk >= 0 && def >= 0)
		{
			return atk > def
				? 1.0 - (def + 2.0) * (2.0 * def + 3.0) / (atk + 1.0) / (atk + 1.0) / 6.0
				: atk * (4.0 * atk + 5.0) / 6.0 / (atk + 1.0) / (def + 1.0);
		}
		if (atk >= 0)
		{
			return 1.0 - 1.0 / (-def + 1.0) / (atk + 1.0);
		}
		if (def >= 0)
		{
			return 0.0;
		}
		double reversedAttack = -def;
		double reversedDefence = -atk;
		return reversedAttack < reversedDefence
			? reversedAttack * (reversedDefence * 6.0 - 2.0 * reversedAttack + 5.0) / 6.0 / (reversedDefence + 1.0) / (reversedDefence + 1.0)
			: 1.0 - (reversedDefence + 2.0) * (2.0 * reversedDefence + 3.0) / 6.0 / (reversedDefence + 1.0) / (reversedAttack + 1.0);
	}

	/**
	 * Expected damage from a standard attack, given the chance it lands. A landed hit rolls uniformly over
	 * {@code 0..maxHit}; the mean weirdgloop's calculator uses is {@code maxHit/2 + 1/(maxHit+1)}, which
	 * this reproduces (matching the {@code best-dps} BSD-2 plugin's {@code normalExpectedHit}).
	 */
	public static double standardExpectedHit(double accuracy, int maxHit)
	{
		if (maxHit <= 0 || accuracy <= 0.0)
		{
			return 0.0;
		}
		return accuracy * (maxHit / 2.0 + 1.0 / (maxHit + 1.0));
	}

	/** Damage per second from an expected per-attack hit and the weapon's attack speed in ticks. */
	public static double dps(double expectedHit, int attackSpeedTicks)
	{
		return expectedHit / (attackSpeedTicks * SECONDS_PER_TICK);
	}

	public static long attackRoll(int effectiveAttack, int attackBonus)
	{
		return (long) effectiveAttack * (attackBonus + 64L);
	}

	public static long defenceRoll(int effectiveDefence, int defenceBonus)
	{
		return (long) effectiveDefence * (defenceBonus + 64L);
	}

	/**
	 * Chance for a hit to land, comparing the attacker's roll to the defender's. Handles negative rolls
	 * (from stacked defence reductions) with the game's documented reflection at zero.
	 */
	public static double normalAccuracy(long attackRoll, long defenceRoll)
	{
		double atk = attackRoll;
		double def = defenceRoll;
		if (atk < 0)
		{
			atk = Math.min(0, atk + 2);
		}
		if (def < 0)
		{
			def = Math.min(0, def + 2);
		}
		if (atk >= 0 && def >= 0)
		{
			return atk > def
				? 1.0 - ((def + 2.0) / (2.0 * (atk + 1.0)))
				: atk / (2.0 * (def + 1.0));
		}
		if (atk >= 0)
		{
			return 1.0 - 1.0 / ((-def + 1.0) * (atk + 1.0));
		}
		if (def >= 0)
		{
			return 0.0;
		}
		double swappedAtk = -def;
		double swappedDef = -atk;
		return swappedAtk > swappedDef
			? 1.0 - ((swappedDef + 2.0) / (2.0 * (swappedAtk + 1.0)))
			: swappedAtk / (2.0 * (swappedDef + 1.0));
	}
}

package com.github.diogogdias.bisfinder.engine;

/**
 * Melee max hit and hit chance, built directly from the OSRS Wiki DPS formulas
 * (https://oldschool.runescape.wiki/w/Damage_per_second/Melee). No higher-level effects (weapon
 * passives, slayer/salve multipliers, specs) are modelled here yet — those are layered on separately.
 */
public final class MeleeCalc
{
	/** NPCs add a flat 9 to their Defence level to get an effective defence for the roll. */
	private static final int NPC_EFFECTIVE_DEFENCE_BONUS = 9;

	/** Void melee: effective attack and strength levels are increased by 10%, rounded down. */
	private static final Factor VOID_MELEE = new Factor(11, 10);

	private MeleeCalc()
	{
	}

	/**
	 * Effective attack or strength level: {@code floor(currentLevel * prayer) + stanceBonus + 8}, then a
	 * 10% void increase when the void set is worn.
	 */
	public static int effectiveLevel(int level, int boost, Factor prayer, int stanceBonus, boolean voidBonus)
	{
		int current = level + boost;
		int effective = prayer.applyFloor(current) + stanceBonus + 8;
		if (voidBonus)
		{
			effective = VOID_MELEE.applyFloor(effective);
		}
		return effective;
	}

	public static int maxHit(int effectiveStrength, int strengthBonus)
	{
		return RollMath.maxHitFromEffective(effectiveStrength, strengthBonus);
	}

	public static long monsterDefenceRoll(int monsterDefenceLevel, int monsterStyleDefenceBonus)
	{
		return RollMath.defenceRoll(monsterDefenceLevel + NPC_EFFECTIVE_DEFENCE_BONUS, monsterStyleDefenceBonus);
	}

	public static double hitChance(int effectiveAttack, int attackBonus,
		int monsterDefenceLevel, int monsterStyleDefenceBonus)
	{
		long attackRoll = RollMath.attackRoll(effectiveAttack, attackBonus);
		long defenceRoll = monsterDefenceRoll(monsterDefenceLevel, monsterStyleDefenceBonus);
		return RollMath.normalAccuracy(attackRoll, defenceRoll);
	}
}

package com.github.diogogdias.bisfinder.engine;

/**
 * An integer multiplier expressed as {@code numerator / denominator}, applied with truncation toward
 * negative infinity — the way the game applies prayer bonuses, void, and similar level multipliers.
 */
public final class Factor
{
	private final long numerator;
	private final long denominator;

	public Factor(long numerator, long denominator)
	{
		if (denominator <= 0)
		{
			throw new IllegalArgumentException("denominator must be positive");
		}
		this.numerator = numerator;
		this.denominator = denominator;
	}

	public static Factor identity()
	{
		return new Factor(1, 1);
	}

	/** {@code floor(value * numerator / denominator)}. */
	public int applyFloor(int value)
	{
		return (int) Math.floorDiv((long) value * numerator, denominator);
	}

	/** {@code floor(value * numerator / denominator)} for roll-sized values. */
	public long applyFloor(long value)
	{
		return Math.floorDiv(value * numerator, denominator);
	}
}

package com.github.diogogdias.bisfinder.engine;

import com.github.diogogdias.bisfinder.calc.Constants;
import com.github.diogogdias.bisfinder.calc.model.CombatStyleStance;
import com.github.diogogdias.bisfinder.calc.model.CombatStyleType;
import com.github.diogogdias.bisfinder.calc.model.EquipmentPiece;
import com.github.diogogdias.bisfinder.calc.model.Monster;
import com.github.diogogdias.bisfinder.calc.model.MonsterAttribute;
import com.github.diogogdias.bisfinder.calc.model.Player;
import com.github.diogogdias.bisfinder.calc.model.Prayer;
import com.github.diogogdias.bisfinder.calc.model.Spell;
import java.util.Arrays;
import java.util.List;
import java.util.Locale;

/**
 * Assembles a full attack from the proven pieces: effective levels (with prayer / stance / void), base
 * max hit and roll, gear/context multipliers, then a hit distribution, then DPS. Reads factual constants
 * (prayer multipliers) off the data model at runtime rather than restating them.
 *
 * <p>Melee only for now; ranged and magic reuse the same shape. It consumes a {@link Player} whose gear
 * bonuses are already aggregated ({@link Player#withGearBonuses}); the aggregation is a separate layer.
 */
public final class DpsEngine
{
	private DpsEngine()
	{
	}

	/** Dispatches to the style-specific DPS. Returns 0 for setups the engine cannot yet score. */
	public static double dps(Player player, Monster monster)
	{
		if (player == null || player.getStyle() == null)
		{
			return 0;
		}
		double dps;
		switch (player.getStyle().getType())
		{
			case MAGIC:
				dps = magicDps(player, monster);
				break;
			case RANGED:
				dps = rangedDps(player, monster);
				break;
			default:
				dps = meleeDps(player, monster);
				break;
		}
		return Double.isFinite(dps) ? dps : 0;
	}

	/** DPS plus the headline numbers the panel shows: the (summed) max hit and the hit chance. */
	public static Estimate estimate(Player player, Monster monster)
	{
		if (player == null || player.getStyle() == null)
		{
			return Estimate.ZERO;
		}
		switch (player.getStyle().getType())
		{
			case MAGIC:
				return magicEstimate(player, monster);
			case RANGED:
				return rangedEstimate(player, monster);
			default:
				return meleeEstimate(player, monster);
		}
	}

	/** A scored attack: the DPS, the max hit shown (summed over a multi-hit weapon's splats) and hit chance. */
	public static final class Estimate
	{
		static final Estimate ZERO = new Estimate(0, 0, 0);

		private final double dps;
		private final int maxHit;
		private final double accuracy;

		Estimate(double dps, int maxHit, double accuracy)
		{
			this.dps = Double.isFinite(dps) ? dps : 0;
			this.maxHit = maxHit;
			this.accuracy = accuracy;
		}

		static Estimate of(AttackDistribution distribution, int attackSpeedTicks)
		{
			int maxHit = 0;
			for (Hitsplat hitsplat : distribution.getHitsplats())
			{
				maxHit += hitsplat.getMaxHit();
			}
			double accuracy = distribution.getHitsplats().isEmpty()
				? 0 : distribution.getHitsplats().get(0).getAccuracy();
			return new Estimate(distribution.dps(attackSpeedTicks), maxHit, accuracy);
		}

		public double getDps()
		{
			return dps;
		}

		public int getMaxHit()
		{
			return maxHit;
		}

		public double getAccuracy()
		{
			return accuracy;
		}
	}

	public static double meleeDps(Player player, Monster monster)
	{
		return meleeEstimate(player, monster).getDps();
	}

	public static Estimate meleeEstimate(Player player, Monster monster)
	{
		CombatStyleType type = player.getStyle().getType();
		CombatStyleStance stance = player.getStyle().getStance();

		if (!meleeCanReach(player, monster) || immuneToStyle(player, monster))
		{
			return Estimate.ZERO;
		}

		int effStrength = MeleeCalc.effectiveLevel(
			player.getSkills().getStr(), player.getBoosts().getStr(),
			strengthPrayer(player.getPrayers()), strengthStance(stance), hasVoidMelee(player));
		effStrength += soulreaperStrengthBonus(player);
		int effAttack = MeleeCalc.effectiveLevel(
			player.getSkills().getAtk(), player.getBoosts().getAtk(),
			accuracyPrayer(player.getPrayers()), attackStance(stance), hasVoidMelee(player));

		int baseMax = MeleeCalc.maxHit(effStrength, player.getBonuses().getStr());
		long baseRoll = RollMath.attackRoll(effAttack, player.getOffensive().forStyle(type));

		Modifier weaponMod = meleeWeaponModifier(player, monster);
		int max = weaponMod.damage.applyFloor(baseMax);
		long roll = weaponMod.accuracy.applyFloor(baseRoll);

		// The salve / black mask bonus stacks on top of a weapon or set bonus (DHL, Inquisitor).
		Modifier task = taskModifier(player, monster, type);
		max = task.damage.applyFloor(max);
		roll = task.accuracy.applyFloor(roll);

		Modifier bane = baneModifier(player, monster);
		max = bane.damage.applyFloor(max);
		roll = bane.accuracy.applyFloor(roll);

		Modifier wilderness = wilderness(player);
		max = wilderness.damage.applyFloor(max);
		roll = wilderness.accuracy.applyFloor(roll);
		max = monsterDamageFactor(player, monster).applyFloor(max);

		// Colossal blade: flat +2 max hit per tile of the target's size, capped at +10.
		if ("Colossal blade".equals(nameOf(player.getEquipment().getWeapon())))
		{
			max += Math.min(monster.getSize() * 2, 10);
		}

		max += ratbaneMaxBonus(player, monster);

		long defenceRoll = raidScaled(monster,
			RollMath.defenceRoll(effectiveDefenceLevel(monster) + 9, monsterDefence(monster, type)));

		// Osmumten's fang always deals 15%-85% of max, but its twice-rolled accuracy only applies on stab.
		if (isFang(player.getEquipment().getWeapon()))
		{
			int fangMin = (int) Math.floor(max * 0.15);
			double fangAcc = type == CombatStyleType.STAB
				? RollMath.fangAccuracy(roll, defenceRoll)
				: RollMath.normalAccuracy(roll, defenceRoll);
			return Estimate.of(AttackDistribution.single(new Hitsplat(fangAcc, fangMin, max - fangMin)),
				player.getAttackSpeed());
		}

		double accuracy = RollMath.normalAccuracy(roll, defenceRoll);
		return Estimate.of(hitStructure(player, monster, accuracy, max), player.getAttackSpeed());
	}

	/** A gear/context bonus: separate accuracy and damage multipliers, each folded with a floor. */
	private static final class Modifier
	{
		static final Modifier NONE = new Modifier(Factor.identity(), Factor.identity());

		final Factor accuracy;
		final Factor damage;

		Modifier(Factor accuracy, Factor damage)
		{
			this.accuracy = accuracy;
			this.damage = damage;
		}

		static Modifier both(int numerator, int denominator)
		{
			Factor f = new Factor(numerator, denominator);
			return new Modifier(f, f);
		}
	}

	public static double rangedDps(Player player, Monster monster)
	{
		return rangedEstimate(player, monster).getDps();
	}

	public static Estimate rangedEstimate(Player player, Monster monster)
	{
		if (immuneToStyle(player, monster))
		{
			return Estimate.ZERO;
		}

		CombatStyleStance stance = player.getStyle().getStance();
		boolean voidSet = hasVoidRanged(player);

		// Eclipse atlatl / Hunter's spear scale their max hit off Strength (skill and gear bonus), not Ranged.
		boolean scalesWithStr = isStrScalingRanged(player);
		int strLevel = scalesWithStr ? player.getSkills().getStr() : player.getSkills().getRanged();
		int strBoost = scalesWithStr ? player.getBoosts().getStr() : player.getBoosts().getRanged();
		int strBonus = scalesWithStr ? player.getBonuses().getStr() : player.getBonuses().getRangedStr();

		int effStrength = RangedCalc.effectiveLevel(
			strLevel, strBoost, strengthPrayer(player.getPrayers()), rangedStrengthStance(stance), voidSet);
		if (hasEliteVoidRanged(player))
		{
			// Elite void's +2.5% ranged damage is applied to the effective strength, then floored.
			effStrength = new Factor(41, 40).applyFloor(effStrength);
		}
		int effAttack = RangedCalc.effectiveLevel(
			player.getSkills().getRanged(), player.getBoosts().getRanged(),
			accuracyPrayer(player.getPrayers()), rangedAttackStance(stance), voidSet);

		Modifier modifier = rangedModifier(player, monster);
		int max = modifier.damage.applyFloor(RangedCalc.maxHit(effStrength, strBonus));
		long roll = modifier.accuracy.applyFloor(RollMath.attackRoll(effAttack, player.getOffensive().getRanged()));

		// The salve (imbued only) or an imbued black mask on task, stacked on the weapon's own modifier.
		Modifier task = taskModifier(player, monster, CombatStyleType.RANGED);
		max = task.damage.applyFloor(max);
		roll = task.accuracy.applyFloor(roll);

		Modifier bane = baneModifier(player, monster);
		max = bane.damage.applyFloor(max);
		roll = bane.accuracy.applyFloor(roll);
		max += ratbaneMaxBonus(player, monster);

		Modifier wilderness = wilderness(player);
		max = wilderness.damage.applyFloor(max);
		roll = wilderness.accuracy.applyFloor(roll);
		max = monsterDamageFactor(player, monster).applyFloor(max);

		// Tonalztics of ralos throws a glaive that rolls 75% of max hit (it can hit twice, handled below).
		if ("Tonalztics of ralos".equals(nameOf(player.getEquipment().getWeapon())))
		{
			max = new Factor(3, 4).applyFloor(max);
		}

		long defenceRoll = raidScaled(monster,
			RollMath.defenceRoll(effectiveDefenceLevel(monster) + 9, rangedDefence(player, monster)));
		double accuracy = RollMath.normalAccuracy(roll, defenceRoll);

		double expectedHit = boltProcExpectedHit(player, accuracy, max);
		if (expectedHit < 0)
		{
			expectedHit = RollMath.standardExpectedHit(accuracy, max);
		}
		// Dark bow fires two arrows per attack, and a charged Tonalztics of ralos throws two glaives - both
		// are two identical standard hits (the uncharged Tonalztics and everything else roll one).
		EquipmentPiece weapon = player.getEquipment().getWeapon();
		int hits = "Dark bow".equals(nameOf(weapon))
			|| (weapon != null && "Tonalztics of ralos".equals(weapon.getName()) && "Charged".equals(weapon.getVersion()))
			? 2 : 1;
		double dps = RollMath.dps(expectedHit * hits, player.getAttackSpeed());
		return new Estimate(dps, max * hits, accuracy);
	}

	private static boolean isStrScalingRanged(Player player)
	{
		String weapon = nameOf(player.getEquipment().getWeapon());
		return weapon.equals("Eclipse atlatl") || weapon.equals("Hunter's spear");
	}

	private static final List<String> MAGIC_DEF_USES_DEFENCE_LEVEL = Arrays.asList(
		"Verzik Vitur", "Ice demon", "Fragment of Seren", "Baboon Brawler");

	private static boolean usesDefenceLevelForMagicDefence(Monster monster)
	{
		return MAGIC_DEF_USES_DEFENCE_LEVEL.contains(monster.getName());
	}

	/**
	 * Expected hit for an enchanted-bolt proc, or -1 when the ammo has no modelled proc. A proc replaces a
	 * fraction of attacks (raised by the Kandarin hard diary) with a special hit.
	 */
	private static double boltProcExpectedHit(Player player, double accuracy, int max)
	{
		String ammo = nameOf(player.getEquipment().getAmmo());
		double normal = RollMath.standardExpectedHit(accuracy, max);

		if (ammo.equals("Diamond bolts (e)") || ammo.equals("Diamond dragon bolts (e)"))
		{
			double chance = player.getBuffs().isKandarinDiary() ? 0.11 : 0.10;
			// +15% damage and the proc always hits.
			double proc = RollMath.standardExpectedHit(1.0, new Factor(23, 20).applyFloor(max));
			return (1.0 - chance) * normal + chance * proc;
		}
		return -1.0;
	}

	public static double magicDps(Player player, Monster monster)
	{
		return magicEstimate(player, monster).getDps();
	}

	public static Estimate magicEstimate(Player player, Monster monster)
	{
		if (immuneToStyle(player, monster))
		{
			return Estimate.ZERO;
		}

		int magicLevel = player.getSkills().getMagic();
		int currentMagic = magicLevel + player.getBoosts().getMagic();

		EquipmentPiece weapon = player.getEquipment().getWeapon();
		boolean poweredStaff = weapon != null
			&& weapon.getCategory() == com.github.diogogdias.bisfinder.calc.model.EquipmentCategory.POWERED_STAFF;
		int stanceBonus = poweredStaff ? magicPoweredStance(player.getStyle().getStance()) : 0;

		int effMagic = MagicCalc.effectiveLevel(magicLevel, player.getBoosts().getMagic(),
			accuracyPrayer(player.getPrayers()), stanceBonus, false);

		int baseMax = player.getSpell() != null
			? spellBaseMax(player, currentMagic)
			: poweredStaffBaseMax(nameOf(weapon), currentMagic);
		if (baseMax <= 0)
		{
			// No spell and an unmodelled powered staff (trident, sanguinesti, ...): cannot score yet.
			return Estimate.ZERO;
		}
		int magicDamage = player.getBonuses().getMagicStr() + magicDamagePrayer(player.getPrayers());
		int weakness = elementalWeaknessSeverity(player, monster);

		// The salve (imbued) or an imbued black mask on task adds to the magic-damage pool rather than
		// multiplying the max hit, and multiplies the attack roll via taskModifier below.
		magicDamage += taskMagicDamage(player, monster);

		int max = MagicCalc.maxHit(baseMax, magicDamage) + (int) Math.floor((double) baseMax * weakness / 100.0);
		long roll = RollMath.attackRoll(effMagic, player.getOffensive().getMagic());
		if (weakness > 0)
		{
			roll = new Factor(100 + weakness, 100).applyFloor(roll);
		}

		Modifier task = taskModifier(player, monster, CombatStyleType.MAGIC);
		roll = task.accuracy.applyFloor(roll);

		// The Dragon hunter wand is a staff, so its dragonbane bonus used to sit in the melee path - where it
		// only ever fired if you bashed a dragon with it, never when casting, which is the whole point of it.
		if ("Dragon hunter wand".equals(nameOf(weapon)) && hasAttribute(monster, MonsterAttribute.DRAGON))
		{
			max = new Factor(6, 5).applyFloor(max);
			roll = new Factor(6, 5).applyFloor(roll);
		}

		Modifier wilderness = wilderness(player);
		max = wilderness.damage.applyFloor(max);
		roll = wilderness.accuracy.applyFloor(roll);
		// Most NPCs defend magic with their Magic level, but a few (Verzik, Ice demon, Fragment of Seren,
		// Baboon brawler) use their Defence level instead.
		int magicDefLevel = usesDefenceLevelForMagicDefence(monster)
			? monster.getSkills().getDef() : monster.getSkills().getMagic();
		long defenceRoll = raidScaled(monster,
			RollMath.defenceRoll(magicDefLevel + 9, monster.getDefensive().getMagic()));
		double accuracy = RollMath.normalAccuracy(roll, defenceRoll);

		// The Sanguinesti staff's heal now deals 8 extra damage when it procs (2026 Summer Sweep-Up), on 1 in
		// 5 successful hits. Like the enchanted-bolt procs, this adds to DPS while the shown max hit stays the
		// base roll: the +8 is a rare bonus, not the number the spell usually lands.
		if (nameOf(weapon).contains("anguinesti staff"))
		{
			double expectedHit = RollMath.standardExpectedHit(accuracy, max) + accuracy * 0.2 * 8.0;
			return new Estimate(RollMath.dps(expectedHit, player.getAttackSpeed()), max, accuracy);
		}

		return Estimate.of(AttackDistribution.single(Hitsplat.standard(accuracy, max)), player.getAttackSpeed());
	}

	// --- prayers ------------------------------------------------------------------------------------

	private static Factor strengthPrayer(List<Prayer> prayers)
	{
		for (Prayer prayer : prayers)
		{
			if (prayer.getFactorStrength() != null)
			{
				return new Factor(prayer.getFactorStrength().getFactor(), prayer.getFactorStrength().getDivisor());
			}
		}
		return Factor.identity();
	}

	private static Factor accuracyPrayer(List<Prayer> prayers)
	{
		for (Prayer prayer : prayers)
		{
			if (prayer.getFactorAccuracy() != null)
			{
				return new Factor(prayer.getFactorAccuracy().getFactor(), prayer.getFactorAccuracy().getDivisor());
			}
		}
		return Factor.identity();
	}

	// --- stance -------------------------------------------------------------------------------------

	private static int attackStance(CombatStyleStance stance)
	{
		switch (stance)
		{
			case ACCURATE:
				return 3;
			case CONTROLLED:
				return 1;
			default:
				return 0;
		}
	}

	private static int strengthStance(CombatStyleStance stance)
	{
		switch (stance)
		{
			case AGGRESSIVE:
				return 3;
			case CONTROLLED:
				return 1;
			default:
				return 0;
		}
	}

	private static int rangedAttackStance(CombatStyleStance stance)
	{
		return stance == CombatStyleStance.ACCURATE ? 3 : 0;
	}

	private static int rangedStrengthStance(CombatStyleStance stance)
	{
		// Ranged uses one level for both rolls, so Accurate's +3 boosts max hit too (not just accuracy).
		return stance == CombatStyleStance.ACCURATE ? 3 : 0;
	}

	private static int magicDamagePrayer(List<Prayer> prayers)
	{
		int total = 0;
		for (Prayer prayer : prayers)
		{
			total += prayer.getMagicDamageBonus();
		}
		return total;
	}

	/** Severity of the monster's elemental weakness if the spell's element matches it, else 0. */
	private static int elementalWeaknessSeverity(Player player, Monster monster)
	{
		Spell spell = player.getSpell();
		Monster.Weakness weakness = monster.getWeakness();
		if (spell == null || spell.getElement() == null || weakness == null || weakness.getElement() == null)
		{
			return 0;
		}
		return spell.getElement().equalsIgnoreCase(weakness.getElement()) ? weakness.getSeverity() : 0;
	}

	private static int magicPoweredStance(CombatStyleStance stance)
	{
		// Powered staves use a +8 effective-level base (vs +9 for cast spells), so relative to MagicCalc's
		// +9 the Accurate stance's +3 nets to +2 and Longrange's +1 nets to 0.
		switch (stance)
		{
			case ACCURATE:
				return 2;
			case LONGRANGE:
				return 0;
			default:
				return -1;
		}
	}

	/**
	 * A spell's base max hit. Almost every spell carries its own in the data, but Magic Dart's is listed as 0
	 * because it scales with the caster: floor(magic * 0.1) + 10, or floor(magic * 0.166) + 13 with a Slayer's
	 * staff (e) on task. Without this it scored nothing, which mattered once leafy creatures started refusing
	 * every spell but this one.
	 */
	private static int spellBaseMax(Player player, int currentMagic)
	{
		Spell spell = player.getSpell();
		if (!"Magic Dart".equals(spell.getName()))
		{
			return spell.getMaxHit();
		}

		boolean enchantedOnTask = "Slayer's staff (e)".equals(nameOf(player.getEquipment().getWeapon()))
			&& player.getBuffs().isOnSlayerTask();
		return enchantedOnTask
			? (int) Math.floor(currentMagic * 0.166) + 13
			: (int) Math.floor(currentMagic * 0.1) + 10;
	}

	/**
	 * Base max hit of a powered staff from the visible (boosted) magic level, before magic-damage bonuses.
	 * Returns -1 for a staff whose formula is not modelled, which scores the setup at zero rather than
	 * guessing.
	 *
	 * <p>Every formula here was taken from the staff's own wiki page and reconciled against a worked example
	 * on that page (e.g. the swamp trident's "starting at 24 damage with level 78 Magic" → 78/3-2 = 24).
	 * That check matters: the wiki renders these as stacked fractions, which flatten into ambiguous text when
	 * scraped — "⌊8(Magic Level)+9637⌋" is really ⌊(8·magic+96)/37⌋. A formula that cannot be reconciled
	 * against a stated data point is left out rather than guessed at; see docs/architecture/engine-gaps.md.
	 */
	private static int poweredStaffBaseMax(String weapon, int magicLevel)
	{
		// The seas/swamp tridents each have (e), (o) and (e) (o) variants that only change the look.
		if (weapon.startsWith("Trident of the seas"))
		{
			return magicLevel / 3 - 5;
		}
		if (weapon.startsWith("Trident of the swamp"))
		{
			return magicLevel / 3 - 2;
		}

		switch (weapon)
		{
			case "Tumeken's shadow":
				return magicLevel / 3 + 1;
			case "Sanguinesti staff":
			case "Holy sanguinesti staff":
				// The holy kit is cosmetic: "Though its stats do not change". Base max raised by 1 in the 2026
				// Summer Sweep-Up: "27 at 82 Magic" reconciles floor(82/3) = 27.
				return magicLevel / 3;
			case "Thammaron's sceptre":
			case "Thammaron's sceptre (a)":
				return magicLevel / 3 - 8;
			case "Accursed sceptre":
			case "Accursed sceptre (a)":
				return magicLevel / 3 - 6;
			case "Eye of ayak":
				return magicLevel / 3 - 6;
			case "Warped sceptre":
				return (8 * magicLevel + 96) / 37;
			default:
				return -1;
		}
	}

	// --- gear / context multipliers -----------------------------------------------------------------

	/**
	 * The weapon/set multiplier: the Dragon hunter lance's dragonbane, or the Inquisitor set's crush bonus.
	 *
	 * <p>The black mask is deliberately not here. It is a separate source that stacks multiplicatively with
	 * these ("This stacks multiplicatively with both Void Knight equipment and the Slayer helm (i)"), so
	 * folding it into this either/or chain let a Dragon hunter lance silently swallow it on a dragon task.
	 * See {@link #taskModifier}.
	 */
	private static Modifier meleeWeaponModifier(Player player, Monster monster)
	{
		String weaponName = nameOf(player.getEquipment().getWeapon());
		CombatStyleType type = player.getStyle().getType();

		if (weaponName.equals("Dragon hunter lance") && hasAttribute(monster, MonsterAttribute.DRAGON))
		{
			return Modifier.both(6, 5);
		}

		if (type == CombatStyleType.CRUSH)
		{
			// The 2026 Summer Sweep-Up removed the Inquisitor set bonus and the mace's tripling of it, moving
			// the crush boost onto the individual pieces (great helm +0.5%, hauberk +1%, plateskirt +1%) so
			// they now count on their own. The mace's benefit is its own +7 strength / +7 crush stats.
			Player.PlayerEquipment e = player.getEquipment();
			int tenths = 0;
			if (nameOf(e.getHead()).equals("Inquisitor's great helm"))
			{
				tenths += 5;
			}
			if (nameOf(e.getBody()).equals("Inquisitor's hauberk"))
			{
				tenths += 10;
			}
			if (nameOf(e.getLegs()).equals("Inquisitor's plateskirt"))
			{
				tenths += 10;
			}
			if (tenths > 0)
			{
				return Modifier.both(1000 + tenths, 1000);
			}
		}

		return Modifier.NONE;
	}

	/**
	 * The salve amulet's undead bonus, or the black mask's on-task bonus - never both. Mod Ash: "Salve
	 * effects override the Slayer helm / black mask effects (because they're either identical or bigger)."
	 *
	 * <p>The black mask is +16.67% to melee for every variant, and a further +15% to Ranged and +15% to
	 * Magic for the imbued ones only. Magic is handled separately, because a magic damage bonus is added to
	 * the damage pool rather than multiplied onto the max hit; this returns only its accuracy there.
	 */
	private static Modifier taskModifier(Player player, Monster monster, CombatStyleType type)
	{
		Modifier salve = type.isMelee() ? meleeSalve(player, monster) : salveImbued(player, monster);
		if (salve != null)
		{
			return salve;
		}

		if (!onTaskWithBlackMask(player))
		{
			return Modifier.NONE;
		}

		if (type.isMelee())
		{
			return Modifier.both(7, 6);
		}

		// Ranged and Magic only get a bonus from an imbued mask.
		if (!isImbued(nameOf(player.getEquipment().getHead())))
		{
			return Modifier.NONE;
		}
		return type == CombatStyleType.MAGIC
			? new Modifier(new Factor(23, 20), Factor.identity())
			: Modifier.both(23, 20);
	}

	/**
	 * The extra magic damage (in tenths of a percent, as the damage pool counts it) from the salve or an
	 * imbued black mask on task. Mirrors {@link #taskModifier}: the salve wins when both are worn.
	 */
	private static int taskMagicDamage(Player player, Monster monster)
	{
		Modifier salve = salveImbued(player, monster);
		if (salve != null)
		{
			return salve == SALVE_EI ? 200 : 150;
		}
		return onTaskWithBlackMask(player) && isImbued(nameOf(player.getEquipment().getHead())) ? 150 : 0;
	}

	/** Melee salve against the undead: enchanted is 20%, base/imbued is 15%. */
	private static Modifier meleeSalve(Player player, Monster monster)
	{
		if (!isUndead(monster))
		{
			return null;
		}
		switch (nameOf(player.getEquipment().getNeck()))
		{
			case "Salve amulet(ei)":
			case "Salve amulet (e)":
				return Modifier.both(6, 5);
			case "Salve amulet(i)":
			case "Salve amulet":
				return Modifier.both(23, 20);
			default:
				return null;
		}
	}

	private static Modifier rangedModifier(Player player, Monster monster)
	{
		String weapon = nameOf(player.getEquipment().getWeapon());
		if (weapon.equals("Dragon hunter crossbow") && hasAttribute(monster, MonsterAttribute.DRAGON))
		{
			return new Modifier(new Factor(13, 10), new Factor(5, 4));
		}
		if (weapon.equals("Twisted bow"))
		{
			return twistedBow(monster);
		}
		return Modifier.NONE;
	}

	/**
	 * Twisted bow accuracy and damage scale with the target's Magic level, per the wiki formula. The target's
	 * effective magic is capped at 250, or 350 against Xerician (Chambers of Xeric) monsters. The resulting
	 * percentage is NOT clamped to its base — near the cap the accuracy bonus reaches 141%.
	 */
	private static Modifier twistedBow(Monster monster)
	{
		int cap = hasAttribute(monster, MonsterAttribute.XERICIAN) ? 350 : 250;
		int magic = Math.min(cap, Math.max(monster.getSkills().getMagic(), monster.getOffensive().getMagic()));
		return new Modifier(new Factor(tbowScale(magic, true), 100), new Factor(tbowScale(magic, false), 100));
	}

	/** Percentage (out of 100) the Twisted bow multiplies its accuracy (factor 10/140) or damage (14/250) by. */
	private static int tbowScale(int magic, boolean accuracyMode)
	{
		int factor = accuracyMode ? 10 : 14;
		int base = accuracyMode ? 140 : 250;
		int t2 = (3 * magic - factor) / 100;
		int inner = 3 * magic / 10 - 10 * factor;
		int t3 = (inner * inner) / 100;
		return base + t2 - t3;
	}

	private static boolean hasEliteVoidRanged(Player player)
	{
		Player.PlayerEquipment e = player.getEquipment();
		return nameOf(e.getHead()).equals("Void ranger helm")
			&& nameOf(e.getBody()).equals("Elite void top")
			&& nameOf(e.getLegs()).equals("Elite void robe")
			&& nameOf(e.getHands()).equals("Void knight gloves");
	}

	/** The revenant-ether weapons, whose charged form is powered up in the Wilderness. */
	private static final List<String> WILDERNESS_WEAPONS = Arrays.asList(
		"Craw's bow", "Webweaver bow",
		"Viggora's chainmace", "Ursine chainmace",
		"Thammaron's sceptre", "Thammaron's sceptre (a)",
		"Accursed sceptre", "Accursed sceptre (a)");

	/**
	 * A charged revenant-ether weapon hits NPCs in the Wilderness 50% harder and 50% more accurately. The
	 * bonus needs the charge: an uncharged one is a plain weapon, and the wiki data tells the two apart by
	 * version rather than by name.
	 *
	 * <p>Only the bows and the chainmaces can reach this today. The two sceptres are powered staves, which
	 * {@link #poweredStaffBaseMax} does not model yet, so magic bails out before the multiplier is read; the
	 * magic side is wired up so that modelling them is all it takes.
	 */
	private static Modifier wilderness(Player player)
	{
		if (!player.getBuffs().isInWilderness())
		{
			return Modifier.NONE;
		}
		EquipmentPiece weapon = player.getEquipment().getWeapon();
		if (weapon == null || !WILDERNESS_WEAPONS.contains(weapon.getName())
			|| !"Charged".equals(weapon.getVersion()))
		{
			return Modifier.NONE;
		}
		return Modifier.both(3, 2);
	}

	private static final Modifier SALVE_EI = Modifier.both(6, 5);
	private static final Modifier SALVE_I = Modifier.both(23, 20);

	/** Imbued salve (works for every style) against the undead: (ei) is 20%, (i) is 15%. */
	private static Modifier salveImbued(Player player, Monster monster)
	{
		if (!isUndead(monster))
		{
			return null;
		}
		String neck = nameOf(player.getEquipment().getNeck());
		if (neck.equals("Salve amulet(ei)"))
		{
			return SALVE_EI;
		}
		if (neck.equals("Salve amulet(i)"))
		{
			return SALVE_I;
		}
		return null;
	}

	/**
	 * The monster's Defence level after the reductions the user has entered (Advanced options). Percentage
	 * reductions take a cut of the current level in turn; flat reductions (BGS) subtract a fixed amount.
	 */
	private static int effectiveDefenceLevel(Monster monster)
	{
		int def = monster.getSkills().getDef();
		com.github.diogogdias.bisfinder.calc.model.MonsterInputs.DefenceReductions dr =
			monster.getInputs().getDefenceReductions();
		for (int i = 0; i < dr.getElderMaul(); i++)
		{
			def -= def * 35 / 100;
		}
		for (int i = 0; i < dr.getDwh(); i++)
		{
			def -= def * 30 / 100;
		}
		if (dr.isAccursed())
		{
			def -= def * 15 / 100;
		}
		if (dr.isVulnerability())
		{
			def -= def * 10 / 100;
		}

		// Flat drains, subtracted after the percentage cuts. A Tonalztics of ralos "Division" hit lowers the
		// Defence level by 12.5% of the target's Magic level (raised from 10% in the 2026 Summer Sweep-Up); a
		// charged special is two hits, so it is counted per hit here.
		int magicLevel = monster.getSkills().getMagic();
		for (int i = 0; i < dr.getTonalztic(); i++)
		{
			def -= magicLevel * 125 / 1000;
		}
		def -= dr.getBgs();
		return Math.max(0, def);
	}

	/** Tombs of Amascut scales the defence roll by +2% for every 5 raid (invocation) levels. */
	private static long raidScaled(Monster monster, long defenceRoll)
	{
		int invocation = monster.getInputs().getToaInvocationLevel();
		if (invocation <= 0)
		{
			return defenceRoll;
		}
		return defenceRoll * (100 + (invocation / 5) * 2) / 100;
	}

	/** Monster-specific damage reduction (Bitterkoekje/wiki mechanics), applied to the max hit. */
	private static Factor monsterDamageFactor(Player player, Monster monster)
	{
		if ("Corporeal Beast".equals(monster.getName()))
		{
			// Takes half damage from everything except spears and the crystal halberd.
			EquipmentPiece weapon = player.getEquipment().getWeapon();
			boolean spear = weapon != null
				&& (weapon.getCategory() == com.github.diogogdias.bisfinder.calc.model.EquipmentCategory.SPEAR
				|| "Crystal halberd".equals(weapon.getName()));
			return spear ? Factor.identity() : new Factor(1, 2);
		}
		return Factor.identity();
	}

	/** Soulreaper axe: each soul stack adds 6% of the current strength level to the effective strength. */
	private static int soulreaperStrengthBonus(Player player)
	{
		String weapon = nameOf(player.getEquipment().getWeapon());
		if (!"Soulreaper axe".equals(weapon) && !"Soulreaper axe (o)".equals(weapon))
		{
			return 0;
		}
		int strengthLevel = player.getSkills().getStr() + player.getBoosts().getStr();
		return strengthLevel * 6 * player.getBuffs().getSoulreaperStacks() / 100;
	}

	private static boolean isReachWeapon(Player player)
	{
		EquipmentPiece weapon = player.getEquipment().getWeapon();
		return weapon != null
			&& weapon.getCategory() == com.github.diogogdias.bisfinder.calc.model.EquipmentCategory.POLEARM;
	}

	private static boolean isSalamander(Player player)
	{
		EquipmentPiece weapon = player.getEquipment().getWeapon();
		return weapon != null
			&& weapon.getCategory() == com.github.diogogdias.bisfinder.calc.model.EquipmentCategory.SALAMANDER;
	}

	/**
	 * Whether melee can physically reach the target, which is a separate question from whether melee hurts it.
	 *
	 * <p>A halberd strikes from a tile away, and so does a salamander's scorch. That reach is what makes a
	 * flying enemy meleeable (since 25 June 2025, for every flying enemy rather than just aviansies), and it
	 * is the only way to touch Zulrah, which swims out of range of anything shorter.
	 */
	private static boolean meleeCanReach(Player player, Monster monster)
	{
		if (Constants.ZULRAH_IDS.contains(monster.getId()))
		{
			// A salamander's scorch is not enough here: the wiki is explicit that only halberds reach Zulrah.
			return isReachWeapon(player);
		}
		if (hasAttribute(monster, MonsterAttribute.FLYING))
		{
			return isReachWeapon(player) || isSalamander(player);
		}
		return true;
	}

	/**
	 * Whether this style simply cannot hurt the target, and so scores nothing rather than a number the
	 * player could never achieve. The Kraken and the Leviathan are out of melee's reach even with a halberd;
	 * Tekton and Dusk shrug off arrows.
	 *
	 * <p>{@link Constants#IMMUNE_TO_NON_SALAMANDER_MELEE_DAMAGE_NPC_IDS} is deliberately not consulted: it
	 * predates the 25 June 2025 change that let halberds hit every flying enemy, so enforcing it would wrongly
	 * zero a halberd at aviansies. Reach is handled by {@link #meleeCanReach} instead.
	 */
	private static boolean immuneToStyle(Player player, Monster monster)
	{
		int id = monster.getId();
		CombatStyleType type = player.getStyle().getType();

		if (hasAttribute(monster, MonsterAttribute.LEAFY) && !canDamageLeafy(player, type))
		{
			return true;
		}

		if (type == CombatStyleType.MAGIC)
		{
			return Constants.IMMUNE_TO_MAGIC_DAMAGE_NPC_IDS.contains(id);
		}
		if (!type.isMelee())
		{
			return Constants.IMMUNE_TO_RANGED_DAMAGE_NPC_IDS.contains(id);
		}
		return Constants.IMMUNE_TO_MELEE_DAMAGE_NPC_IDS.contains(id);
	}

	/**
	 * A black mask or any slayer helmet, on task.
	 *
	 * <p>The helmet is matched on "slayer helmet" anywhere in the name rather than as a prefix: the plain
	 * "Slayer helmet" is the exception, and the fourteen themed ones the game actually hands out (Purple,
	 * Hydra, Araxyte, Oathplate, Tzkal, ...) all put their colour first. Matching the prefix meant a player
	 * in a coloured helm got no on-task bonus at all.
	 */
	private static boolean onTaskWithBlackMask(Player player)
	{
		if (!player.getBuffs().isOnSlayerTask())
		{
			return false;
		}
		String head = nameOf(player.getEquipment().getHead());
		return head.startsWith("Black mask")
			|| head.toLowerCase(Locale.ROOT).contains("slayer helmet");
	}

	/** The imbued variants, which alone carry the Ranged and Magic bonuses, are the ones suffixed "(i)". */
	private static boolean isImbued(String head)
	{
		return head.endsWith("(i)");
	}

	/** The leaf-bladed weapons, the only melee a Kurask or Turoth can be hurt by. */
	private static final List<String> LEAF_BLADED = Arrays.asList(
		"Leaf-bladed battleaxe", "Leaf-bladed spear", "Leaf-bladed sword");

	/** Broad-tipped ammunition, the only ranged a Kurask or Turoth can be hurt by. */
	private static final List<String> BROAD_AMMO = Arrays.asList(
		"Broad arrows", "Broad bolts", "Amethyst broad bolts");

	/**
	 * The rat bone weapons from Scurrius. Listed rather than matched on a "Bone " prefix, which would drag in
	 * the Bone dagger, club and spear - Dorgeshuun and barbarian gear with no ratbane effect at all.
	 */
	private static final List<String> RATBANE = Arrays.asList("Bone mace", "Bone shortbow", "Bone staff");

	/**
	 * A weapon's bonus against the kind of thing it was built to kill. Each is the weapon's own multiplier,
	 * applied only when the target carries the matching attribute.
	 *
	 * <p>Duke Sucellus is the lone demon that resists demonbane, by 30% - which is what turns Arclight's 70%
	 * into 49% there. (The wiki data has a {@code demonbaneVulnerability} input for this, but nothing fills
	 * it in: the code that did was the deleted calculator's {@code sanitizeInputs}.)
	 */
	private static Modifier baneModifier(Player player, Monster monster)
	{
		String weapon = nameOf(player.getEquipment().getWeapon());

		if (hasAttribute(monster, MonsterAttribute.DEMON))
		{
			int accuracy;
			int damage;
			switch (weapon)
			{
				case "Silverlight":
				case "Silverlight (dyed)":
				case "Darklight":
					accuracy = 0;
					damage = 60;
					break;
				case "Arclight":
				case "Emberlight":
					accuracy = 70;
					damage = 70;
					break;
				case "Scorching bow":
					accuracy = 30;
					damage = 30;
					break;
				case "Burning claws":
					accuracy = 5;
					damage = 5;
					break;
				default:
					accuracy = 0;
					damage = 0;
					break;
			}

			if ("Duke Sucellus".equals(monster.getName()))
			{
				accuracy = accuracy * 7 / 10;
				damage = damage * 7 / 10;
			}
			if (damage > 0 || accuracy > 0)
			{
				return new Modifier(new Factor(100 + accuracy, 100), new Factor(100 + damage, 100));
			}
		}

		// Every keris keeps the original's 33% against kalphites and scabarites, except the partisan of
		// amascut: "this variant has a damage bonus of 15%, down from the base weapon's 33%", traded for far
		// better stats inside Tombs of Amascut. The partisan of breaching adds 33% accuracy on top.
		// The 1/51 triple-damage proc every keris has is not modelled - see docs/architecture/engine-gaps.md.
		if (hasAttribute(monster, MonsterAttribute.KALPHITE) && weapon.startsWith("Keris"))
		{
			int damage = "Keris partisan of amascut".equals(weapon) ? 15 : 33;
			int accuracy = "Keris partisan of breaching".equals(weapon) ? 33 : 0;
			return new Modifier(new Factor(100 + accuracy, 100), new Factor(100 + damage, 100));
		}

		if (hasAttribute(monster, MonsterAttribute.GOLEM) && "Barronite mace".equals(weapon))
		{
			return Modifier.both(23, 20);
		}

		// Only the battleaxe: "Unlike the leaf-bladed battleaxe, the sword does not have a 17.5% damage buff".
		if (hasAttribute(monster, MonsterAttribute.LEAFY) && "Leaf-bladed battleaxe".equals(weapon))
		{
			return new Modifier(Factor.identity(), new Factor(47, 40));
		}

		return Modifier.NONE;
	}

	/** Ratbane weapons add a flat 10 to the max hit against rats, rather than a percentage. */
	private static int ratbaneMaxBonus(Player player, Monster monster)
	{
		return hasAttribute(monster, MonsterAttribute.RAT)
			&& RATBANE.contains(nameOf(player.getEquipment().getWeapon())) ? 10 : 0;
	}

	/**
	 * Whether this style can hurt a leafy creature at all: "they can only be damaged with leaf-bladed
	 * weapons, broad ammunition, or the Magic Dart spell; they are immune to any other types of attacks."
	 */
	private static boolean canDamageLeafy(Player player, CombatStyleType type)
	{
		if (type == CombatStyleType.MAGIC)
		{
			Spell spell = player.getSpell();
			return spell != null && "Magic Dart".equals(spell.getName());
		}
		if (type.isMelee())
		{
			return LEAF_BLADED.contains(nameOf(player.getEquipment().getWeapon()));
		}
		return BROAD_AMMO.contains(nameOf(player.getEquipment().getAmmo()));
	}

	// --- hit structure ------------------------------------------------------------------------------

	private static final List<String> TWO_HIT_WEAPONS = Arrays.asList(
		"Torag's hammers", "Sulphur blades", "Glacial temotli", "Earthbound tecpatl");

	private static AttackDistribution hitStructure(Player player, Monster monster, double accuracy, int max)
	{
		String weapon = nameOf(player.getEquipment().getWeapon());
		// Scythe of vitur (incl. Holy/Sanguine variants): hits once per tile of the target's size, up to
		// three times, at 100% / 50% / 25% of max.
		if (weapon.contains("of vitur"))
		{
			int hits = Math.min(monster.getSize(), 3);
			if (hits >= 3)
			{
				return AttackDistribution.of(Hitsplat.standard(accuracy, max),
					Hitsplat.standard(accuracy, max / 2), Hitsplat.standard(accuracy, max / 4));
			}
			if (hits == 2)
			{
				return AttackDistribution.of(Hitsplat.standard(accuracy, max),
					Hitsplat.standard(accuracy, max / 2));
			}
			return AttackDistribution.single(Hitsplat.standard(accuracy, max));
		}
		// Two-hit weapons split the max into two independent splats (firstMax + secondMax = max), each with
		// the weapon's accuracy. The two smaller splats each carry their own +1/(max+1) term.
		if (TWO_HIT_WEAPONS.contains(weapon))
		{
			int firstMax = max / 2;
			int secondMax = max - firstMax;
			return AttackDistribution.of(Hitsplat.standard(accuracy, firstMax),
				Hitsplat.standard(accuracy, secondMax));
		}
		// Dual macuahuitl (without the Blood moon set): the second splat only rolls if the first lands, so
		// its expected damage is discounted by the first hit's accuracy.
		if (weapon.equals("Dual macuahuitl") && !hasBloodMoonSet(player))
		{
			int firstMax = max / 2;
			int secondMax = max - firstMax;
			return AttackDistribution.of(Hitsplat.standard(accuracy, firstMax),
				new Hitsplat(accuracy * accuracy, 0, secondMax));
		}
		return AttackDistribution.single(Hitsplat.standard(accuracy, max));
	}

	// --- helpers ------------------------------------------------------------------------------------

	private static final List<String> VOID_BODY = Arrays.asList("Void knight top", "Elite void top");
	private static final List<String> VOID_LEGS = Arrays.asList("Void knight robe", "Elite void robe");

	private static boolean hasVoidMelee(Player player)
	{
		Player.PlayerEquipment e = player.getEquipment();
		return nameOf(e.getHead()).equals("Void melee helm")
			&& VOID_BODY.contains(nameOf(e.getBody()))
			&& VOID_LEGS.contains(nameOf(e.getLegs()))
			&& nameOf(e.getHands()).equals("Void knight gloves");
	}

	private static boolean hasVoidRanged(Player player)
	{
		Player.PlayerEquipment e = player.getEquipment();
		return nameOf(e.getHead()).equals("Void ranger helm")
			&& VOID_BODY.contains(nameOf(e.getBody()))
			&& VOID_LEGS.contains(nameOf(e.getLegs()))
			&& nameOf(e.getHands()).equals("Void knight gloves");
	}

	/** Monster ranged defence for the ammo's damage type: crossbows heavy, thrown light, otherwise standard. */
	private static int rangedDefence(Player player, Monster monster)
	{
		EquipmentPiece weapon = player.getEquipment().getWeapon();
		if (weapon != null)
		{
			switch (weapon.getCategory())
			{
				case CROSSBOW:
					return monster.getDefensive().getHeavy();
				case THROWN:
				case CHINCHOMPA:
					return monster.getDefensive().getLight();
				default:
					break;
			}
		}
		return monster.getDefensive().getStandard();
	}

	private static int monsterDefence(Monster monster, CombatStyleType type)
	{
		switch (type)
		{
			case STAB:
				return monster.getDefensive().getStab();
			case SLASH:
				return monster.getDefensive().getSlash();
			case CRUSH:
				return monster.getDefensive().getCrush();
			default:
				throw new IllegalArgumentException("not a melee type: " + type);
		}
	}

	private static boolean isUndead(Monster monster)
	{
		return hasAttribute(monster, MonsterAttribute.UNDEAD);
	}

	private static boolean hasAttribute(Monster monster, MonsterAttribute attribute)
	{
		return monster.getAttributes().contains(attribute);
	}

	private static String nameOf(EquipmentPiece piece)
	{
		return piece == null ? "" : piece.getName();
	}

	private static boolean isFang(EquipmentPiece weapon)
	{
		String name = nameOf(weapon);
		return name.equals("Osmumten's fang") || name.equals("Osmumten's fang (or)");
	}

	private static boolean hasBloodMoonSet(Player player)
	{
		Player.PlayerEquipment e = player.getEquipment();
		return nameOf(e.getWeapon()).equals("Dual macuahuitl")
			&& nameOf(e.getHead()).equals("Blood moon helm")
			&& nameOf(e.getBody()).equals("Blood moon chestplate")
			&& nameOf(e.getLegs()).equals("Blood moon tassets");
	}
}

package com.github.diogogdias.bisfinder;

import com.github.diogogdias.bisfinder.calc.Constants;
import com.github.diogogdias.bisfinder.calc.Equipment;
import com.github.diogogdias.bisfinder.engine.DpsEngine;
import com.github.diogogdias.bisfinder.calc.model.CombatStyleType;
import com.github.diogogdias.bisfinder.calc.model.EquipmentPiece;
import com.github.diogogdias.bisfinder.calc.model.Monster;
import com.github.diogogdias.bisfinder.calc.model.MonsterAttribute;
import com.github.diogogdias.bisfinder.calc.model.Player;
import com.github.diogogdias.bisfinder.calc.model.PlayerBuffs;
import com.github.diogogdias.bisfinder.calc.model.PlayerCombatStyle;
import com.github.diogogdias.bisfinder.calc.model.PlayerSkills;
import com.github.diogogdias.bisfinder.calc.model.Potion;
import com.github.diogogdias.bisfinder.calc.model.Prayer;
import com.github.diogogdias.bisfinder.calc.model.Spell;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.Comparator;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.stream.Collectors;
import lombok.Value;

/**
 * Finds the highest-DPS setup a player can build from the items they own, by asking the ported wiki
 * calculator for the DPS of real loadouts.
 *
 * <p>The search is a hill climb, which is what gearscape.net's own best-in-slot worker does: hold a
 * loadout, try every candidate item for one slot at a time, keep whatever improves DPS, and sweep until
 * a pass changes nothing. The weapon is just another slot, so a better weapon is found the same way as
 * a better ring. Scoring every candidate with the real calculator means set effects, bolt procs and
 * target-specific bonuses are all priced correctly rather than guessed at.
 *
 * <p>Two things stop the climb from getting stuck. Candidates are pruned by dominance first, so the
 * search only ever considers items that could win. And because a hill climb cannot cross a valley — a
 * void piece is a downgrade until all four are worn — the climb is repeated from several seeds: the
 * strongest weapons of each attack type, and every complete set the player owns, with the set's slots
 * pinned. The answer is the best result over all seeds.
 */
public class BisOptimizer
{
	/**
	 * Sets worth wearing only as a set. Each becomes a seed with its slots pinned, so the climb can reach
	 * a setup that only pays off once every piece is worn.
	 */
	private static final List<List<String>> SETS = Arrays.asList(
		Arrays.asList("Void melee helm", "Void knight top", "Void knight robe", "Void knight gloves"),
		Arrays.asList("Void ranger helm", "Void knight top", "Void knight robe", "Void knight gloves"),
		Arrays.asList("Void mage helm", "Void knight top", "Void knight robe", "Void knight gloves"),
		Arrays.asList("Void melee helm", "Elite void top", "Elite void robe", "Void knight gloves"),
		Arrays.asList("Void ranger helm", "Elite void top", "Elite void robe", "Void knight gloves"),
		Arrays.asList("Void mage helm", "Elite void top", "Elite void robe", "Void knight gloves"),
		Arrays.asList("Obsidian helmet", "Obsidian platebody", "Obsidian platelegs"),
		Arrays.asList("Crystal helm", "Crystal body", "Crystal legs"),
		Arrays.asList("Inquisitor's great helm", "Inquisitor's hauberk", "Inquisitor's plateskirt"),
		Arrays.asList("Dharok's helm", "Dharok's platebody", "Dharok's platelegs"),
		Arrays.asList("Virtus mask", "Virtus robe top", "Virtus robe bottom")
	);

	private static final Set<String> SET_PIECES = SETS.stream()
		.flatMap(List::stream)
		.collect(Collectors.toSet());

	private static final List<String> ARMOUR_SLOTS =
		Arrays.asList("head", "cape", "neck", "ammo", "body", "shield", "legs", "hands", "feet", "ring");

	/**
	 * Gauntlet and Corrupted Gauntlet gear, which is destroyed on leaving the Gauntlet and so can never be
	 * in a bank. These item ids are excluded from the search.
	 */
	private static final Set<Integer> UNBANKABLE = Collections.unmodifiableSet(new HashSet<>(Arrays.asList(
		23861, 23862, 23863, 23864, 23886, 23887, 23888, 23889, 23890, 23891, 23892, 23893, 23894, 23895,
		23896, 23897, 23898, 23899, 23900, 23901, 23902, 23903,
		23820, 23821, 23822, 23823, 23840, 23841, 23842, 23843, 23844, 23845, 23846, 23847, 23848, 23849,
		23850, 23851, 23852, 23853, 23854, 23855, 23856, 23857
	)));

	/** How many of the strongest weapons per attack type are used as starting points for the climb. */
	private static final int WEAPON_SEEDS_PER_TYPE = 3;

	/** How many items per slot are tried in the two-slot pass; the rest lost on their own merits. */
	private static final int PAIR_CANDIDATES = 6;

	/** The climb settles in two or three sweeps; the cap only bounds a pathological case. */
	private static final int MAX_SWEEPS = 5;

	private Options options = Options.auto();

	@Value
	public static class Result
	{
		Player player;
		double dps;
		int maxHit;
		double accuracy;
		PlayerCombatStyle style;

		/** The prayer and potion the DPS assumes, so the number is never read as unboosted. */
		Prayer prayer;
		Potion potion;

		/** Melee, ranged or magic - which of the three this is the best setup for. */
		Style styleGroup;

		/** The weapon's special attack, or null when it has none the calculator supports. */
		Spec spec;

		/** Total prayer bonus of the setup, after the spare slots are spent on prayer gear. */
		int prayerBonus;
	}

	/**
	 * What the weapon's special attack does with this setup. The DPS figure is the calculator's own: the
	 * damage the spec adds per second, given how fast the energy comes back (halved by a Lightbearer).
	 */
	@Value
	public static class Spec
	{
		int maxHit;
		double accuracy;
		double dps;
		int cost;
	}

	/** A weapon paired with one of its combat styles, and the spell it would cast. */
	@Value
	private static class Armament
	{
		EquipmentPiece weapon;
		PlayerCombatStyle style;
		Spell spell;
	}

	/**
	 * What the player wants assumed, rather than what the search would assume for them. A null prayer or
	 * potion means "pick the best for the style"; {@link Prayer} has no NONE, so praying nothing is an
	 * empty prayer list, which is what {@code noPrayer} is for.
	 */
	@Value
	public static class Options
	{
		Prayer prayer;
		Potion potion;
		boolean noPrayer;
		Set<Integer> excludedItems;

		public static Options auto()
		{
			return new Options(null, null, false, Collections.emptySet());
		}
	}

	public Result findBest(List<EquipmentPiece> allEquipment, List<Spell> spells, Set<Integer> ownedIds,
		PlayerSkills skills, PlayerBuffs buffs, Monster monster)
	{
		return findBest(allEquipment, spells, ownedIds, skills, buffs, monster, Options.auto());
	}

	public Result findBest(List<EquipmentPiece> allEquipment, List<Spell> spells, Set<Integer> ownedIds,
		PlayerSkills skills, PlayerBuffs buffs, Monster monster, Options options)
	{
		List<Result> byStyle = findBestPerStyle(allEquipment, spells, ownedIds, skills, buffs, monster, options);
		return byStyle.isEmpty() ? null : byStyle.get(0);
	}

	/**
	 * The best setup for each of melee, ranged and magic, strongest first — the way gearscape shows them,
	 * so the cost of picking a style you would rather use is visible instead of hidden.
	 *
	 * <p>A style is only listed if the player owns something that can use it against this target.
	 */
	public List<Result> findBestPerStyle(List<EquipmentPiece> allEquipment, List<Spell> spells,
		Set<Integer> ownedIds, PlayerSkills skills, PlayerBuffs buffs, Monster monster, Options options)
	{
		this.options = options;

		List<EquipmentPiece> owned = ownedEquipment(allEquipment, ownedIds);

		List<Armament> armaments = armaments(owned, spells, skills, monster);
		if (armaments.isEmpty())
		{
			return Collections.emptyList();
		}

		Map<String, List<EquipmentPiece>> bySlot = owned.stream()
			.filter(piece -> !"weapon".equals(piece.getSlot()))
			.collect(Collectors.groupingBy(EquipmentPiece::getSlot));

		// Keyed by attack type (stab/slash/crush/ranged/magic) so the melee styles are reported separately -
		// the sidebar shows the best stab, slash and crush setup, since which one wins shifts by target.
		Map<CombatStyleType, Player> best = new EnumMap<>(CombatStyleType.class);
		Map<CombatStyleType, Double> bestDps = new EnumMap<>(CombatStyleType.class);

		for (Seed seed : seeds(armaments, bySlot))
		{
			Player player = climb(seed, armaments, bySlot, skills, buffs, monster);
			if (player == null)
			{
				continue;
			}

			double dps = dps(player, monster);
			CombatStyleType key = player.getStyle().getType();

			if (dps > 0 && dps > bestDps.getOrDefault(key, 0.0))
			{
				bestDps.put(key, dps);
				best.put(key, player);
			}
		}

		List<Result> results = new ArrayList<>();
		for (Map.Entry<CombatStyleType, Player> entry : best.entrySet())
		{
			Player climbed = improveInPairs(entry.getValue(), bySlot, monster);
			Player player = fillWithPrayerGear(climbed, bySlot, monster);
			CombatStyleType type = player.getStyle().getType();

			// Recompute on the final gear: improveInPairs/fillWithPrayerGear change the setup after the
			// climb, so the climb's stored numbers are stale for the loadout actually shown.
			DpsEngine.Estimate estimate = DpsEngine.estimate(player, monster);
			results.add(new Result(player, estimate.getDps(), estimate.getMaxHit(), estimate.getAccuracy(),
				player.getStyle(), prayers(type).isEmpty() ? null : prayers(type).get(0), potion(type),
				Style.of(type), null, player.getBonuses().getPrayer()));
		}

		results.sort(Comparator.comparingDouble(Result::getDps).reversed());
		return results;
	}

	/**
	 * Changes two slots at once, which a one-slot-at-a-time climb cannot.
	 *
	 * <p>Some pairs of items only win together. At Bloat a Torva helm with an Oathplate chest beats an
	 * Oathplate helm with a Torva chest — but from the second, swapping either slot on its own makes things
	 * worse, so the climb sits there believing it is finished. This tries every pair of slots against every
	 * pair of their candidates, and keeps going while it finds something.
	 *
	 * <p>Only the leading candidates for a slot are paired up: pairing everything against everything would
	 * be a much bigger search for gear that was already beaten on its own merits.
	 */
	private Player improveInPairs(Player player, Map<String, List<EquipmentPiece>> bySlot, Monster monster)
	{
		Player current = player;

		for (int pass = 0; pass < MAX_SWEEPS; pass++)
		{
			double currentDps = dps(current, monster);
			boolean improved = false;

			for (int i = 0; i < ARMOUR_SLOTS.size() && !improved; i++)
			{
				for (int j = i + 1; j < ARMOUR_SLOTS.size() && !improved; j++)
				{
					String slotA = ARMOUR_SLOTS.get(i);
					String slotB = ARMOUR_SLOTS.get(j);

					for (EquipmentPiece a : pairCandidates(slotA, current, bySlot))
					{
						for (EquipmentPiece b : pairCandidates(slotB, current, bySlot))
						{
							Player trial = current.toBuilder()
								.equipment(current.getEquipment()
									.withSlot(slotA, a)
									.withSlot(slotB, b))
								.build()
								.withGearBonuses(monster);

							double dps = dps(trial, monster);
							if (dps > currentDps + 1e-9)
							{
								currentDps = dps;
								current = trial;
								improved = true;
							}
						}
					}
				}
			}

			if (!improved)
			{
				break;
			}
		}

		return current;
	}

	/** The few items in a slot worth pairing with another slot's, plus whatever is worn there now. */
	private List<EquipmentPiece> pairCandidates(String slot, Player player,
		Map<String, List<EquipmentPiece>> bySlot)
	{
		if ("shield".equals(slot) && player.getEquipment().getWeapon().isTwoHanded())
		{
			return Collections.emptyList();
		}

		CombatStyleType type = player.getStyle().getType();

		List<EquipmentPiece> items = bySlot.getOrDefault(slot, Collections.emptyList()).stream()
			.filter(item -> !"ammo".equals(slot) || Equipment.ammoApplicability(
				player.getEquipment().getWeapon().getId(), item.getId())
				== Equipment.AmmoApplicability.INCLUDED)
			.sorted(Comparator
				.comparingInt((EquipmentPiece item) -> strength(item, type) + accuracy(item, type))
				.reversed())
			.limit(PAIR_CANDIDATES)
			.collect(Collectors.toList());

		return items;
	}

	/**
	 * Once the DPS is settled, spends the slots that are not paying for themselves on prayer bonus.
	 *
	 * <p>A slot only changes if the swap costs no DPS at all: an empty ammo slot on a melee setup, or a
	 * cape whose offensive bonuses the target does not care about, becomes the highest-prayer item the
	 * player owns for that slot. Nothing here can make a setup weaker — a candidate that loses even a
	 * fraction of a point of DPS is rejected.
	 */
	private Player fillWithPrayerGear(Player player, Map<String, List<EquipmentPiece>> bySlot, Monster monster)
	{
		Player current = player;
		double target = dps(current, monster);

		for (String slot : ARMOUR_SLOTS)
		{
			EquipmentPiece worn = current.getEquipment().bySlot().get(slot);

			if ("shield".equals(slot) && current.getEquipment().getWeapon().isTwoHanded())
			{
				continue;
			}

			int bestPrayer = worn == null ? 0 : worn.getBonuses().getPrayer();
			Player best = current;

			int wornOffence = offensiveStrength(worn);
			for (EquipmentPiece candidate : bySlot.getOrDefault(slot, Collections.emptyList()))
			{
				if (candidate.getBonuses().getPrayer() <= bestPrayer)
				{
					continue;
				}

				// A prayer upgrade must not sacrifice offensive strength - keep Torva over a faceguard even
				// when the max hit ties, rather than trading damage headroom for prayer.
				if (offensiveStrength(candidate) < wornOffence)
				{
					continue;
				}

				// Ammo the weapon cannot hold is not wearable, but ammo it merely tolerates - a blessing on a
				// melee setup - is.
				if ("ammo".equals(slot) && Equipment.ammoApplicability(
					current.getEquipment().getWeapon().getId(), candidate.getId())
					== Equipment.AmmoApplicability.INVALID)
				{
					continue;
				}

				Player trial = current.toBuilder()
					.equipment(current.getEquipment().withSlot(slot, candidate))
					.build()
					.withGearBonuses(monster);

				if (dps(trial, monster) >= target - 1e-9)
				{
					bestPrayer = candidate.getBonuses().getPrayer();
					best = trial;
				}
			}

			current = best;
		}

		return current;
	}

	/** A piece's total offensive strength (melee/ranged/magic), used to break DPS ties toward damage gear. */
	private static int offensiveStrength(EquipmentPiece piece)
	{
		if (piece == null)
		{
			return 0;
		}
		return piece.getBonuses().getStr() + piece.getBonuses().getRangedStr() + piece.getBonuses().getMagicStr();
	}

	/** The three styles a player chooses between; the melee attack types are not separate choices. */
	public enum Style
	{
		MELEE,
		RANGED,
		MAGIC;

		static Style of(CombatStyleType type)
		{
			if (type.isMelee())
			{
				return MELEE;
			}
			return type == CombatStyleType.MAGIC ? MAGIC : RANGED;
		}
	}

	/**
	 * Sweeps the slots, swapping one item at a time for the best candidate, until nothing improves. The
	 * weapon is swapped the same way, which is also where a change of attack style or spell happens.
	 */
	private Player climb(Seed seed, List<Armament> armaments, Map<String, List<EquipmentPiece>> bySlot,
		PlayerSkills skills, PlayerBuffs buffs, Monster monster)
	{
		Armament armament = seed.armament;

		// Start dressed. An empty loadout would leave a bow without ammo, scoring zero damage, and the
		// first weapon swap would abandon ranged before it ever had a chance.
		Map<String, EquipmentPiece> worn = startingKit(armament, bySlot);
		worn.putAll(seed.pinned);

		double currentDps = dps(build(armament, worn, skills, buffs, monster), monster);

		for (int sweep = 0; sweep < MAX_SWEEPS; sweep++)
		{
			boolean improved = false;

			// Only weapons of the same attack type are considered: swapping style mid-climb would need the
			// whole armour set to change with it, which is what the per-type seeds are for.
			for (Armament candidate : armaments)
			{
				if (candidate == armament || candidate.style.getType() != armament.style.getType())
				{
					continue;
				}

				Map<String, EquipmentPiece> trial = compatible(worn, candidate, bySlot);
				double dps = dps(build(candidate, trial, skills, buffs, monster), monster);
				if (dps > currentDps)
				{
					currentDps = dps;
					armament = candidate;
					worn = trial;
					improved = true;
				}
			}

			for (String slot : ARMOUR_SLOTS)
			{
				if (seed.pinned.containsKey(slot))
				{
					continue;
				}
				if ("shield".equals(slot) && armament.weapon.isTwoHanded())
				{
					continue;
				}

				for (EquipmentPiece candidate : candidates(slot, armament, bySlot))
				{
					EquipmentPiece previous = worn.get(slot);
					worn.put(slot, candidate);

					double dps = dps(build(armament, worn, skills, buffs, monster), monster);
					if (dps > currentDps)
					{
						currentDps = dps;
						improved = true;
					}
					else if (previous == null)
					{
						worn.remove(slot);
					}
					else
					{
						worn.put(slot, previous);
					}
				}
			}

			if (!improved)
			{
				break;
			}
		}

		return build(armament, worn, skills, buffs, monster);
	}

	/**
	 * A plausible loadout to start the climb from: the best item in each slot by strength, then accuracy.
	 * It only has to be good enough that the weapon is not wasted — the climb corrects it from there.
	 */
	private Map<String, EquipmentPiece> startingKit(Armament armament, Map<String, List<EquipmentPiece>> bySlot)
	{
		CombatStyleType type = armament.style.getType();
		Map<String, EquipmentPiece> worn = new HashMap<>();

		for (String slot : ARMOUR_SLOTS)
		{
			if ("shield".equals(slot) && armament.weapon.isTwoHanded())
			{
				continue;
			}

			candidates(slot, armament, bySlot).stream()
				.max(Comparator
					.comparingInt((EquipmentPiece item) -> strength(item, type))
					.thenComparingInt(item -> accuracy(item, type)))
				.ifPresent(item -> worn.put(slot, item));
		}
		return worn;
	}

	/**
	 * Fits the worn gear to a weapon the climb is about to try.
	 *
	 * <p>A two-hander drops the shield, and ammo the weapon cannot use is dropped. Crucially, the slots a
	 * weapon *unlocks* are filled straight away: a one-hander gets the best shield, a bow gets its best
	 * ammo. Judging a one-hander while the shield slot is still empty — because the weapon it is replacing
	 * was two-handed — would reject it on a loadout nobody would ever wear, which is how a Blade of
	 * saeldor loses to a scythe it should beat.
	 */
	private Map<String, EquipmentPiece> compatible(Map<String, EquipmentPiece> worn, Armament armament,
		Map<String, List<EquipmentPiece>> bySlot)
	{
		Map<String, EquipmentPiece> trial = new HashMap<>(worn);

		if (armament.weapon.isTwoHanded())
		{
			trial.remove("shield");
		}
		else if (!trial.containsKey("shield"))
		{
			best("shield", armament, bySlot).ifPresent(shield -> trial.put("shield", shield));
		}

		EquipmentPiece ammo = trial.get("ammo");
		if (ammo != null && Equipment.ammoApplicability(armament.weapon.getId(), ammo.getId())
			== Equipment.AmmoApplicability.INVALID)
		{
			trial.remove("ammo");
		}

		if (!trial.containsKey("ammo"))
		{
			best("ammo", armament, bySlot).ifPresent(fresh -> trial.put("ammo", fresh));
		}

		return trial;
	}

	private java.util.Optional<EquipmentPiece> best(String slot, Armament armament,
		Map<String, List<EquipmentPiece>> bySlot)
	{
		CombatStyleType type = armament.style.getType();
		return candidates(slot, armament, bySlot).stream()
			.max(Comparator
				.comparingInt((EquipmentPiece item) -> strength(item, type))
				.thenComparingInt(item -> accuracy(item, type)));
	}

	/**
	 * Per-slot candidates for this style. An item is dropped only when another owned item in the slot is
	 * at least as good on both the accuracy bonus and the strength bonus, which cannot change the answer
	 * for a plain item — but an item the calculator special-cases is never dropped, because its value does
	 * not show up in those two numbers.
	 */
	private List<EquipmentPiece> candidates(String slot, Armament armament,
		Map<String, List<EquipmentPiece>> bySlot)
	{
		List<EquipmentPiece> items = new ArrayList<>(bySlot.getOrDefault(slot, Collections.emptyList()));

		if ("ammo".equals(slot))
		{
			// Only ammo the weapon actually fires. Ammo a melee weapon merely tolerates contributes nothing,
			// and would otherwise be picked arbitrarily among ties and shown as part of the setup.
			items = items.stream()
				.filter(ammo -> Equipment.ammoApplicability(armament.weapon.getId(), ammo.getId())
					== Equipment.AmmoApplicability.INCLUDED)
				.collect(Collectors.toList());
		}

		CombatStyleType type = armament.style.getType();
		List<EquipmentPiece> front = new ArrayList<>();
		for (EquipmentPiece item : items)
		{
			if (isSpecialCased(item) || !dominated(item, items, type))
			{
				front.add(item);
			}
		}
		return front;
	}

	/**
	 * Every weapon the player owns, paired with each of its attack styles, minus the weapons that another
	 * owned weapon beats outright: same handedness, no slower, and at least as good on both the accuracy
	 * and the strength bonus for that style. A weapon with an effect is always kept.
	 */
	private List<Armament> armaments(List<EquipmentPiece> owned, List<Spell> spells, PlayerSkills skills,
		Monster monster)
	{
		// A non-positive attack speed means the item is not really a weapon (greegrees, holiday items). It
		// would otherwise divide DPS by a negative interval and win outright.
		List<EquipmentPiece> weapons = owned.stream()
			.filter(piece -> "weapon".equals(piece.getSlot()))
			.filter(piece -> piece.getSpeed() > 0)
			.map(piece -> loadBlowpipe(piece, owned))
			.collect(Collectors.toList());

		List<Spell> castable = candidateSpells(spells, skills, monster);

		List<Armament> armaments = new ArrayList<>();
		for (EquipmentPiece weapon : weapons)
		{
			for (PlayerCombatStyle style : PlayerCombatStyle.getCombatStylesForCategory(weapon.getCategory()))
			{
				if (style.getType() == null)
				{
					continue;
				}

				if (!EffectItems.matters(weapon.getName())
					&& dominatedWeapon(weapon, weapons, style.getType()))
				{
					continue;
				}

				if (!castsASpell(style))
				{
					armaments.add(new Armament(weapon, style, null));
					continue;
				}

				// The spell is a slot like any other: one armament per candidate, so the climb prices each
				// with the real engine. Picking it up front on max hit alone is what made every magic setup
				// reach for the biggest number in the spellbook regardless of the target.
				for (Spell spell : castable)
				{
					armaments.add(new Armament(weapon, style, spell));
				}
			}
		}
		return armaments;
	}

	private static boolean castsASpell(PlayerCombatStyle style)
	{
		return style.getType() == CombatStyleType.MAGIC
			&& style.getStance() != null
			&& style.getStance().isCastStance();
	}

	/**
	 * A blowpipe is loaded with darts rather than using the ammo slot, and all of its ranged strength
	 * comes from them — an unloaded one is a blowgun with nothing in it. The calculator reads the dart
	 * from the weapon's itemVars, which nothing else fills in, so the best dart the player owns is loaded
	 * here. Darts sit in the "weapon" slot in the wiki data, not "ammo".
	 */
	private EquipmentPiece loadBlowpipe(EquipmentPiece weapon, List<EquipmentPiece> owned)
	{
		if (!Constants.BLOWPIPE_IDS.contains(weapon.getId()))
		{
			return weapon;
		}

		EquipmentPiece dart = owned.stream()
			.filter(piece -> piece.getName().endsWith(" dart"))
			.filter(piece -> piece.getBonuses().getRangedStr() > 0)
			.max(Comparator.comparingInt(piece -> piece.getBonuses().getRangedStr()))
			.orElse(null);

		if (dart == null)
		{
			return weapon;
		}

		return weapon.withItemVars(new EquipmentPiece.ItemVars(dart.getId(), dart.getName()));
	}

	private boolean dominatedWeapon(EquipmentPiece weapon, List<EquipmentPiece> weapons, CombatStyleType type)
	{
		for (EquipmentPiece other : weapons)
		{
			if (other == weapon || other.isTwoHanded() != weapon.isTwoHanded()
				|| other.getSpeed() > weapon.getSpeed())
			{
				continue;
			}

			boolean atLeastAsGood = accuracy(other, type) >= accuracy(weapon, type)
				&& strength(other, type) >= strength(weapon, type);
			boolean strictlyBetter = accuracy(other, type) > accuracy(weapon, type)
				|| strength(other, type) > strength(weapon, type)
				|| other.getSpeed() < weapon.getSpeed();

			if (atLeastAsGood && strictlyBetter)
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * Starting points: the strongest few weapons of each attack type, and every complete set the player
	 * owns, pinned so the climb cannot take it apart one piece at a time.
	 */
	private List<Seed> seeds(List<Armament> armaments, Map<String, List<EquipmentPiece>> bySlot)
	{
		List<Seed> seeds = new ArrayList<>();

		for (CombatStyleType type : CombatStyleType.values())
		{
			armaments.stream()
				.filter(a -> a.style.getType() == type)
				.sorted(Comparator
					.comparingInt((Armament a) -> strength(a.weapon, type))
					.thenComparingInt(a -> accuracy(a.weapon, type))
					.reversed())
				.limit(WEAPON_SEEDS_PER_TYPE)
				.forEach(a -> seeds.add(new Seed(a, Collections.emptyMap())));
		}

		List<Map<String, EquipmentPiece>> sets = ownedSets(bySlot);
		if (!sets.isEmpty())
		{
			List<Seed> withSets = new ArrayList<>();
			for (Seed seed : seeds)
			{
				for (Map<String, EquipmentPiece> set : sets)
				{
					withSets.add(new Seed(seed.armament, set));
				}
			}
			seeds.addAll(withSets);
		}

		return seeds;
	}

	private List<Map<String, EquipmentPiece>> ownedSets(Map<String, List<EquipmentPiece>> bySlot)
	{
		List<Map<String, EquipmentPiece>> sets = new ArrayList<>();

		for (List<String> set : SETS)
		{
			Map<String, EquipmentPiece> pieces = new HashMap<>();
			for (String name : set)
			{
				EquipmentPiece piece = findOwned(bySlot, name);
				if (piece == null)
				{
					pieces = null;
					break;
				}
				pieces.put(piece.getSlot(), piece);
			}

			if (pieces != null && pieces.size() == set.size())
			{
				sets.add(pieces);
			}
		}
		return sets;
	}

	private EquipmentPiece findOwned(Map<String, List<EquipmentPiece>> bySlot, String name)
	{
		for (List<EquipmentPiece> slot : bySlot.values())
		{
			for (EquipmentPiece piece : slot)
			{
				if (piece.getName().equals(name))
				{
					return piece;
				}
			}
		}
		return null;
	}

	private boolean isSpecialCased(EquipmentPiece item)
	{
		return SET_PIECES.contains(item.getName()) || EffectItems.matters(item.getName());
	}

	private boolean dominated(EquipmentPiece item, List<EquipmentPiece> items, CombatStyleType type)
	{
		for (EquipmentPiece other : items)
		{
			if (other == item)
			{
				continue;
			}

			boolean atLeastAsGood = accuracy(other, type) >= accuracy(item, type)
				&& strength(other, type) >= strength(item, type);
			boolean strictlyBetter = accuracy(other, type) > accuracy(item, type)
				|| strength(other, type) > strength(item, type);

			if (atLeastAsGood && strictlyBetter)
			{
				return true;
			}
		}
		return false;
	}

	private int accuracy(EquipmentPiece item, CombatStyleType type)
	{
		EquipmentPiece.Offensive offensive = item.getOffensive();
		switch (type)
		{
			case STAB:
				return offensive.getStab();
			case SLASH:
				return offensive.getSlash();
			case CRUSH:
				return offensive.getCrush();
			case MAGIC:
				return offensive.getMagic();
			default:
				return offensive.getRanged();
		}
	}

	private int strength(EquipmentPiece item, CombatStyleType type)
	{
		EquipmentPiece.Bonuses bonuses = item.getBonuses();
		if (type.isMelee())
		{
			return bonuses.getStr();
		}
		return type == CombatStyleType.MAGIC ? bonuses.getMagicStr() : bonuses.getRangedStr();
	}

	/**
	 * The spells worth trying against this target: the strongest castable one of each element, plus the
	 * strongest castable non-elemental one.
	 *
	 * <p>Only one spell per element is needed, because within an element a bigger max hit always wins — but
	 * the elements must be kept apart, since the target's elemental weakness (up to +50% damage and accuracy)
	 * can make a smaller spell of the right element beat a bigger one of the wrong element. Collapsing them
	 * to a single strongest spell, as this used to, made an elemental weakness unreachable.
	 */
	private List<Spell> candidateSpells(List<Spell> spells, PlayerSkills skills, Monster monster)
	{
		Map<String, Spell> bestByElement = new HashMap<>();
		for (Spell spell : spells)
		{
			if (spell.isBindSpell() || !castable(spell, skills.getMagic(), spells)
				|| !targetable(spell, monster))
			{
				continue;
			}

			String element = spell.getElement() == null ? "" : spell.getElement();
			Spell best = bestByElement.get(element);
			if (best == null || spell.getMaxHit() > best.getMaxHit())
			{
				bestByElement.put(element, spell);
			}
		}
		return new ArrayList<>(bestByElement.values());
	}

	/**
	 * Whether the player's Magic level allows this spell. The spell data carries no level requirement, but
	 * {@link Spell#maxHit} resolves an elemental spell to the strongest element the level allows — so a spell
	 * whose own max hit is above what its tier resolves to is one the player cannot reach yet. Non-elemental
	 * spells have nothing to check against and are assumed castable, as they always have been.
	 */
	private static boolean castable(Spell spell, int magicLevel, List<Spell> spells)
	{
		return spell.getElement() == null
			|| Spell.maxHit(spell, magicLevel, spells) >= spell.getMaxHit();
	}

	/** Demonbane spells only have a demon to be cast at; everything else goes anywhere. */
	private static boolean targetable(Spell spell, Monster monster)
	{
		return !spell.getName().endsWith("Demonbane")
			|| monster.getAttributes().contains(MonsterAttribute.DEMON);
	}

	private Player build(Armament armament, Map<String, EquipmentPiece> worn, PlayerSkills skills,
		PlayerBuffs buffs, Monster monster)
	{
		Player.PlayerEquipment gear = Player.PlayerEquipment.builder().weapon(armament.weapon).build();
		for (Map.Entry<String, EquipmentPiece> entry : worn.entrySet())
		{
			gear = gear.withSlot(entry.getKey(), entry.getValue());
		}

		CombatStyleType type = armament.style.getType();
		return Player.builder()
			.skills(skills)
			.boosts(potion(type).boost(skills))
			.prayers(prayers(type))
			.buffs(buffs)
			.style(armament.style)
			.spell(armament.spell)
			.equipment(gear)
			.build()
			.withGearBonuses(monster);
	}

	/** The player's chosen prayer, or the best one for the style if they have not chosen. */
	private List<Prayer> prayers(CombatStyleType type)
	{
		if (options.isNoPrayer())
		{
			return Collections.emptyList();
		}
		if (options.getPrayer() != null)
		{
			return Collections.singletonList(options.getPrayer());
		}

		if (type.isMelee())
		{
			return Prayer.best(Prayer.PrayerStyle.MELEE);
		}
		return type == CombatStyleType.MAGIC
			? Prayer.best(Prayer.PrayerStyle.MAGIC)
			: Prayer.best(Prayer.PrayerStyle.RANGED);
	}

	/** The player's chosen boost, or the best sensible one for the style if they have not chosen. */
	private Potion potion(CombatStyleType type)
	{
		return options.getPotion() != null ? options.getPotion() : Potion.best(type);
	}

	/** How a candidate setup is scored: the clean-room DPS engine. */
	public static java.util.function.ToDoubleBiFunction<Player, Monster> scorer =
		com.github.diogogdias.bisfinder.engine.DpsEngine::dps;

	private double dps(Player player, Monster monster)
	{
		if (player == null)
		{
			return 0;
		}

		double dps = scorer.applyAsDouble(player, monster);
		return Double.isFinite(dps) ? dps : 0;
	}

	private List<EquipmentPiece> ownedEquipment(List<EquipmentPiece> allEquipment, Set<Integer> ownedIds)
	{
		Set<Integer> canonical = new HashSet<>();
		for (int id : ownedIds)
		{
			canonical.add(Equipment.getCanonicalItemId(id));
		}

		return allEquipment.stream()
			.filter(piece -> canonical.contains(piece.getId()))
			.filter(piece -> !UNBANKABLE.contains(piece.getId()))
			.filter(piece -> !options.getExcludedItems().contains(piece.getId()))
			.collect(Collectors.toList());
	}

	@Value
	private static class Seed
	{
		Armament armament;
		Map<String, EquipmentPiece> pinned;
	}
}

