		JLabel key = new JLabel(name);
		key.setFont(FontManager.getRunescapeSmallFont());
		key.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		key.setPreferredSize(new Dimension(48, 22));

		row.add(key, BorderLayout.WEST);
