/**
 * A monster from the OSRS Wiki DPS calculator's monsters.json. The {@code id} is a real in-game NPC ID,
 * but it is not unique: a handful of monsters appear more than once, distinguished by {@code version}.
 *
 * @see <a href="https://github.com/weirdgloop/osrs-dps-calc/blob/main/cdn/json/monsters.json">monsters.json</a>
 */
@Value
@Builder(toBuilder = true)
public class Monster
{
	int id;
	String name;
	/**
	 * The monster's variant, e.g. "Dragon Slayer II". Empty string when the monster has no variants.
	 */
	String version;
	String image;
	int level;
	/**
	 * Attack speed in ticks.
	 */
	int speed;
	/**
	 * Free-text attack styles from the wiki, e.g. ["Slash", "Magic", "Ranged", "Dragonfire"]. Null in the
	 * JSON for a handful of monsters; {@link #getStyle()} normalises that to an empty list.
	 */
	List<String> style;
	int size;
	/**
	 * Display-only. Usually a plain number but sometimes annotated, e.g. "30 (Magic)". The calculator
	 * computes max hit itself and does not read this.
	 */
	@SerializedName("max_hit")
	String maxHit;
	Skills skills;
	Offensive offensive;
	Defensive defensive;
	List<MonsterAttribute> attributes;
	Immunities immunities;
	@SerializedName("is_slayer_monster")
	boolean slayerMonster;
	/**
	 * Null when the monster has no elemental weakness.
	 */
	Weakness weakness;
	/**
	 * Not present in monsters.json: these are the UI-controlled inputs (party size, invocation level,
	 * current hp, defence reductions, phase, ...) that the calculator scales the monster with. Null on a
	 * freshly deserialised monster; {@link #getInputs()} normalises that to the calculator's defaults.
	 */
	MonsterInputs inputs;

	public List<String> getStyle()
	{
		return style == null ? Collections.emptyList() : style;
	}

	public MonsterInputs getInputs()
	{
		return inputs == null ? MonsterInputs.defaults() : inputs;
	}

	public List<MonsterAttribute> getAttributes()
	{
		return attributes == null ? Collections.emptyList() : attributes;
	}

	@Value
	public static class Skills
	{
		int atk;
		int def;
		int hp;
		int magic;
		int ranged;
		int str;
	}

	@Value
	public static class Offensive
	{
		int atk;
		int magic;
		@SerializedName("magic_str")
		int magicStr;
		int ranged;
		@SerializedName("ranged_str")
		int rangedStr;
		int str;
	}

	@Value
	public static class Defensive
	{
		int stab;
		int slash;
		int crush;
		int magic;
		/**
		 * Ranged defence is split by ranged damage type.
		 */
		int heavy;
		int standard;
		int light;
		@SerializedName("flat_armour")
		int flatArmour;
	}

	@Value
	public static class Immunities
	{
		/**
		 * Null means the monster cannot be burnt at all.
		 */
		BurnImmunity burn;
	}

	@Value
	public static class Weakness
	{
		/**
		 * Spell element: "air", "water", "earth", "fire", or "none".
		 */
		String element;
		int severity;
	}
}

package com.github.diogogdias.bisfinder.calc.model;

import com.github.diogogdias.bisfinder.calc.dist.Factor;
import java.util.Arrays;
import java.util.List;

/**
 * Combat prayers and the multipliers they apply.
 *
 * <p>Factors are given with a denominator of 100 so that additive prayers work out correctly.
 */
public enum Prayer
{
	BURST_OF_STRENGTH("Burst of Strength", PrayerStyle.MELEE, null, Factor.of(105, 100), 0),
	CLARITY_OF_THOUGHT("Clarity of Thought", PrayerStyle.MELEE, Factor.of(105, 100), null, 0),
	SHARP_EYE("Sharp Eye", PrayerStyle.RANGED, Factor.of(105, 100), Factor.of(105, 100), 0),
	MYSTIC_WILL("Mystic Will", PrayerStyle.MAGIC, Factor.of(105, 100), null, 0),
	SUPERHUMAN_STRENGTH("Superhuman Strength", PrayerStyle.MELEE, null, Factor.of(110, 100), 0),
	IMPROVED_REFLEXES("Improved Reflexes", PrayerStyle.MELEE, Factor.of(110, 100), null, 0),
	HAWK_EYE("Hawk Eye", PrayerStyle.RANGED, Factor.of(110, 100), Factor.of(110, 100), 0),
	MYSTIC_LORE("Mystic Lore", PrayerStyle.MAGIC, Factor.of(110, 100), null, 10),
	ULTIMATE_STRENGTH("Ultimate Strength", PrayerStyle.MELEE, null, Factor.of(115, 100), 0),
	INCREDIBLE_REFLEXES("Incredible Reflexes", PrayerStyle.MELEE, Factor.of(115, 100), null, 0),
	EAGLE_EYE("Eagle Eye", PrayerStyle.RANGED, Factor.of(115, 100), Factor.of(115, 100), 0),
	MYSTIC_MIGHT("Mystic Might", PrayerStyle.MAGIC, Factor.of(115, 100), null, 20),
	CHIVALRY("Chivalry", PrayerStyle.MELEE, Factor.of(115, 100), Factor.of(118, 100), 0),
	PIETY("Piety", PrayerStyle.MELEE, Factor.of(120, 100), Factor.of(123, 100), 0),
	RIGOUR("Rigour", PrayerStyle.RANGED, Factor.of(120, 100), Factor.of(123, 100), 0),
	AUGURY("Augury", PrayerStyle.MAGIC, Factor.of(125, 100), null, 40),
	THICK_SKIN("Thick Skin", null, null, null, 0),
	ROCK_SKIN("Rock Skin", null, null, null, 0),
	STEEL_SKIN("Steel Skin", null, null, null, 0),
	DEADEYE("Deadeye", PrayerStyle.RANGED, Factor.of(118, 100), Factor.of(118, 100), 0),
	MYSTIC_VIGOUR("Mystic Vigour", PrayerStyle.MAGIC, Factor.of(118, 100), null, 30);

	public enum PrayerStyle
	{
		MELEE,
		RANGED,
		MAGIC
	}

	private final String prayerName;
	private final PrayerStyle style;
	private final Factor factorAccuracy;
	private final Factor factorStrength;
	private final int magicDamageBonus;

	Prayer(String prayerName, PrayerStyle style, Factor factorAccuracy, Factor factorStrength, int magicDamageBonus)
	{
		this.prayerName = prayerName;
		this.style = style;
		this.factorAccuracy = factorAccuracy;
		this.factorStrength = factorStrength;
		this.magicDamageBonus = magicDamageBonus;
	}

	public String getPrayerName()
	{
		return prayerName;
	}

	public PrayerStyle getStyle()
	{
		return style;
	}

	public Factor getFactorAccuracy()
	{
		return factorAccuracy;
	}

	public Factor getFactorStrength()
	{
		return factorStrength;
	}

	public int getMagicDamageBonus()
	{
		return magicDamageBonus;
	}

	/** The strongest offensive prayer for each style, used when the panel picks prayers for the player. */
	public static List<Prayer> best(PrayerStyle style)
	{
		switch (style)
		{
			case MELEE:
				return Arrays.asList(PIETY);
			case RANGED:
				return Arrays.asList(RIGOUR);
			case MAGIC:
				return Arrays.asList(AUGURY);
			default:
				throw new IllegalArgumentException("unknown style " + style);
		}
	}
}

package com.github.diogogdias.bisfinder.calc.model;

/**
 * The combat-style attack types from the OSRS Wiki DPS data.
 *
 * <p>These map directly onto the monster's defensive bonuses.
 */
public enum CombatStyleType
{
	STAB,
	SLASH,
	CRUSH,
	MAGIC,
	RANGED;

	public boolean isMelee()
	{
		return this == STAB || this == SLASH || this == CRUSH;
	}
}

package com.github.diogogdias.bisfinder.calc.model;

import lombok.Builder;
import lombok.Value;

/**
 * Mirrors the per-monster inputs in the OSRS Wiki DPS data (the inputs object of monsters.json).
 *
 * <p>Fields that users have control over in the UI, which may affect buff applicability, monster
 * scaling, etc. Defaults match the OSRS Wiki calculator's neutral starting inputs.
 */
@Value
@Builder(toBuilder = true)
public class MonsterInputs
{
	@Builder.Default
	boolean isFromCoxCm = false;

	@Builder.Default
	int toaInvocationLevel = 0;

	@Builder.Default
	int toaPathLevel = 0;

	@Builder.Default
	int partyMaxCombatLevel = 126;

	/**
	 * Sum total of cox party members' mining level, used to determine guardians' hp.
	 */
	@Builder.Default
	int partySumMiningLevel = 99;

	@Builder.Default
	int partyMaxHpLevel = 99;

	@Builder.Default
	int partySize = 1;

	/**
	 * The monster's current HP, for effects like Ruby bolt (e), or Vardorvis defence.
	 *
	 * <p>Defaults to 150; callers clamp it to the monster's max hp when it exceeds it.
	 */
	@Builder.Default
	int monsterCurrentHp = 150;

	@Builder.Default
	DefenceReductions defenceReductions = DefenceReductions.builder().build();

	/**
	 * Null when unset. BaseCalc.sanitizeInputs populates it for demons.
	 */
	@Builder.Default
	Integer demonbaneVulnerability = null;

	/**
	 * Null when unset.
	 */
	@Builder.Default
	String phase = null;

	public static MonsterInputs defaults()
	{
		return MonsterInputs.builder().build();
	}

	@Value
	@Builder(toBuilder = true)
	public static class DefenceReductions
	{
		@Builder.Default
		boolean vulnerability = false;

		@Builder.Default
		boolean accursed = false;

		@Builder.Default
		int elderMaul = 0;

		@Builder.Default
		int dwh = 0;

		@Builder.Default
		int arclight = 0;

		@Builder.Default
		int emberlight = 0;

		@Builder.Default
		int bgs = 0;

		@Builder.Default
		int tonalztic = 0;

		@Builder.Default
		int seercull = 0;

		@Builder.Default
		int ayak = 0;
	}
}

package com.github.diogogdias.bisfinder.calc.model;

import com.google.gson.TypeAdapter;
import com.google.gson.annotations.JsonAdapter;
import com.google.gson.stream.JsonReader;
import com.google.gson.stream.JsonToken;
import com.google.gson.stream.JsonWriter;
import java.io.IOException;
import java.util.HashMap;
import java.util.Locale;
import java.util.Map;
import lombok.Getter;

/**
 * The combat style category of a piece of equipment, mirroring the wiki calculator's EquipmentCategory
 * enum.
 *
 * @see <a href="https://oldschool.runescape.wiki/w/Property:Combat_style">Combat style</a>
 */
@JsonAdapter(EquipmentCategory.Adapter.class)
public enum EquipmentCategory
{
	NONE(""),
	TWO_HANDED_SWORD("2h Sword"),
	AXE("Axe"),
	BANNER("Banner"),
	BLADED_STAFF("Bladed Staff"),
	BLASTER("Blaster"),
	BLUDGEON("Bludgeon"),
	BLUNT("Blunt"),
	BOW("Bow"),
	BULWARK("Bulwark"),
	CHINCHOMPA("Chinchompas"),
	CLAW("Claw"),
	CROSSBOW("Crossbow"),
	DAGGER("Dagger"),
	FLAIL("Flail"),
	GUN("Gun"),
	MULTI_MELEE("Multi-Melee"),
	PARTISAN("Partisan"),
	PICKAXE("Pickaxe"),
	POLEARM("Polearm"),
	POLESTAFF("Polestaff"),
	POWERED_STAFF("Powered Staff"),
	POWERED_WAND("Powered Wand"),
	SALAMANDER("Salamander"),
	SCYTHE("Scythe"),
	SLASH_SWORD("Slash Sword"),
	SPEAR("Spear"),
	SPIKED("Spiked"),
	STAB_SWORD("Stab Sword"),
	STAFF("Staff"),
	THROWN("Thrown"),
	UNARMED("Unarmed"),
	WHIP("Whip"),

	/**
	 * Any category the wiki adds that this plugin does not know about yet. Never appears in the JSON.
	 */
	UNKNOWN("Unknown");

	private static final Map<String, EquipmentCategory> BY_JSON_VALUE = new HashMap<>();

	static
	{
		for (EquipmentCategory category : values())
		{
			BY_JSON_VALUE.put(key(category.jsonValue), category);
		}
	}

	@Getter
	private final String jsonValue;

	EquipmentCategory(String jsonValue)
	{
		this.jsonValue = jsonValue;
	}

	/**
	 * Tolerant lookup: unknown or missing categories map to {@link #UNKNOWN} / {@link #NONE} rather than
	 * throwing, so new wiki items do not break parsing.
	 */
	public static EquipmentCategory fromJson(String value)
	{
		if (value == null || value.isEmpty())
		{
			return NONE;
		}

		return BY_JSON_VALUE.getOrDefault(key(value), UNKNOWN);
	}

	private static String key(String value)
	{
		return value.toLowerCase(Locale.ROOT);
	}

	static final class Adapter extends TypeAdapter<EquipmentCategory>
	{
		@Override
		public void write(JsonWriter out, EquipmentCategory value) throws IOException
		{
			out.value(value == null ? null : value.getJsonValue());
		}

		@Override
		public EquipmentCategory read(JsonReader in) throws IOException
		{
			if (in.peek() == JsonToken.NULL)
			{
				in.nextNull();
				return NONE;
			}

			// Qualified: an unqualified fromJson() would resolve to TypeAdapter.fromJson(String).
			return EquipmentCategory.fromJson(in.nextString());
		}
	}
}

package com.github.diogogdias.bisfinder.calc.model;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import lombok.Value;

/** Mirrors a combat style entry from the OSRS Wiki DPS data. */
@Value
public class PlayerCombatStyle
{
	String name;
	CombatStyleType type;
	CombatStyleStance stance;

	/**
	 * The actual player stat is still "ranged", so this is not part of {@link CombatStyleType}.
	 */
	public enum RangedDamageType
	{
		LIGHT,
		STANDARD,
		HEAVY,
		MIXED
	}

	/**
	 * Maps a ranged weapon category to its damage type.
	 */
	public static RangedDamageType getRangedDamageType(EquipmentCategory category)
	{
		switch (category)
		{
			case THROWN:
				return RangedDamageType.LIGHT;

			case BOW:
				return RangedDamageType.STANDARD;

			case CROSSBOW:
			case CHINCHOMPA:
				return RangedDamageType.HEAVY;

			case SALAMANDER:
				return RangedDamageType.MIXED;

			default:
				throw new IllegalArgumentException("Not a ranged weapon category: " + category);
		}
	}

	/**
	 * The combat styles available for a given equipment category. The "Manual Cast" pseudo style is
	 * appended to every category.
	 */
	public static List<PlayerCombatStyle> getCombatStylesForCategory(EquipmentCategory category)
	{
		List<PlayerCombatStyle> ret = new ArrayList<>();
		switch (category)
		{
			case TWO_HANDED_SWORD:
				ret.add(style("Chop", CombatStyleType.SLASH, CombatStyleStance.ACCURATE));
				ret.add(style("Slash", CombatStyleType.SLASH, CombatStyleStance.AGGRESSIVE));
				ret.add(style("Smash", CombatStyleType.CRUSH, CombatStyleStance.AGGRESSIVE));
				ret.add(style("Block", CombatStyleType.SLASH, CombatStyleStance.DEFENSIVE));
				break;
			case BANNER:
				ret.add(style("Lunge", CombatStyleType.STAB, CombatStyleStance.ACCURATE));
				ret.add(style("Swipe", CombatStyleType.SLASH, CombatStyleStance.AGGRESSIVE));
				ret.add(style("Pound", CombatStyleType.CRUSH, CombatStyleStance.CONTROLLED));
				ret.add(style("Block", CombatStyleType.STAB, CombatStyleStance.DEFENSIVE));
				break;
			case BLADED_STAFF:
				ret.add(style("Jab", CombatStyleType.STAB, CombatStyleStance.ACCURATE));
				ret.add(style("Swipe", CombatStyleType.SLASH, CombatStyleStance.AGGRESSIVE));
				ret.add(style("Fend", CombatStyleType.CRUSH, CombatStyleStance.DEFENSIVE));
				ret.add(style("Spell", CombatStyleType.MAGIC, CombatStyleStance.DEFENSIVE_AUTOCAST));
				ret.add(style("Spell", CombatStyleType.MAGIC, CombatStyleStance.AUTOCAST));
				break;
			case BLASTER:
				// TODO? (left unimplemented in the source too)
				return Collections.emptyList();
			case BOW:
			case CROSSBOW:
			case THROWN:
				ret.add(style("Accurate", CombatStyleType.RANGED, CombatStyleStance.ACCURATE));
				ret.add(style("Rapid", CombatStyleType.RANGED, CombatStyleStance.RAPID));
				ret.add(style("Longrange", CombatStyleType.RANGED, CombatStyleStance.LONGRANGE));
				break;
			case GUN:
				ret.add(style("Kick", CombatStyleType.CRUSH, CombatStyleStance.AGGRESSIVE));
				break;
			case BULWARK:
				ret.add(style("Pummel", CombatStyleType.CRUSH, CombatStyleStance.ACCURATE));
				ret.add(style("Block", null, null));
				break;
			case MULTI_MELEE:
				ret.add(style("Poke", CombatStyleType.STAB, CombatStyleStance.ACCURATE));
				ret.add(style("Slash", CombatStyleType.SLASH, CombatStyleStance.AGGRESSIVE));
				ret.add(style("Pound", CombatStyleType.CRUSH, CombatStyleStance.AGGRESSIVE));
				ret.add(style("Block", CombatStyleType.SLASH, CombatStyleStance.DEFENSIVE));
				break;
			case PARTISAN:
				ret.add(style("Stab", CombatStyleType.STAB, CombatStyleStance.ACCURATE));
				ret.add(style("Lunge", CombatStyleType.STAB, CombatStyleStance.AGGRESSIVE));
				ret.add(style("Pound", CombatStyleType.CRUSH, CombatStyleStance.AGGRESSIVE));
				ret.add(style("Block", CombatStyleType.STAB, CombatStyleStance.DEFENSIVE));
				break;
			case PICKAXE:
				ret.add(style("Spike", CombatStyleType.STAB, CombatStyleStance.ACCURATE));
				ret.add(style("Impale", CombatStyleType.STAB, CombatStyleStance.AGGRESSIVE));
				ret.add(style("Smash", CombatStyleType.CRUSH, CombatStyleStance.AGGRESSIVE));
				ret.add(style("Block", CombatStyleType.STAB, CombatStyleStance.DEFENSIVE));
				break;
			case POLEARM:
				ret.add(style("Jab", CombatStyleType.STAB, CombatStyleStance.CONTROLLED));
				ret.add(style("Swipe", CombatStyleType.SLASH, CombatStyleStance.AGGRESSIVE));
				ret.add(style("Fend", CombatStyleType.STAB, CombatStyleStance.DEFENSIVE));
				break;
			case POWERED_STAFF:
			case POWERED_WAND:
				ret.add(style("Accurate", CombatStyleType.MAGIC, CombatStyleStance.ACCURATE));
				ret.add(style("Accurate", CombatStyleType.MAGIC, CombatStyleStance.ACCURATE));
				ret.add(style("Longrange", CombatStyleType.MAGIC, CombatStyleStance.LONGRANGE));
				break;
			case SALAMANDER:
				ret.add(style("Scorch", CombatStyleType.SLASH, CombatStyleStance.AGGRESSIVE));
				ret.add(style("Flare", CombatStyleType.RANGED, CombatStyleStance.RAPID));
				ret.add(style("Blaze", CombatStyleType.MAGIC, CombatStyleStance.DEFENSIVE));
				break;
			case CHINCHOMPA:
				ret.add(style("Short fuse", CombatStyleType.RANGED, CombatStyleStance.ACCURATE));
				ret.add(style("Medium fuse", CombatStyleType.RANGED, CombatStyleStance.RAPID));
				ret.add(style("Long fuse", CombatStyleType.RANGED, CombatStyleStance.LONGRANGE));
				break;
			case CLAW:
				ret.add(style("Chop", CombatStyleType.SLASH, CombatStyleStance.ACCURATE));
				ret.add(style("Slash", CombatStyleType.SLASH, CombatStyleStance.AGGRESSIVE));
				ret.add(style("Lunge", CombatStyleType.STAB, CombatStyleStance.CONTROLLED));
				ret.add(style("Block", CombatStyleType.SLASH, CombatStyleStance.DEFENSIVE));
				break;
			case BLUDGEON:
				ret.add(style("Pound", CombatStyleType.CRUSH, CombatStyleStance.AGGRESSIVE));
				ret.add(style("Pummel", CombatStyleType.CRUSH, CombatStyleStance.AGGRESSIVE));
				ret.add(style("Smash", CombatStyleType.CRUSH, CombatStyleStance.AGGRESSIVE));
				break;
			case BLUNT:
				ret.add(style("Pound", CombatStyleType.CRUSH, CombatStyleStance.ACCURATE));
				ret.add(style("Pummel", CombatStyleType.CRUSH, CombatStyleStance.AGGRESSIVE));
				ret.add(style("Block", CombatStyleType.CRUSH, CombatStyleStance.DEFENSIVE));
				break;
			case POLESTAFF:
				ret.add(style("Bash", CombatStyleType.CRUSH, CombatStyleStance.ACCURATE));
				ret.add(style("Pound", CombatStyleType.CRUSH, CombatStyleStance.AGGRESSIVE));
				ret.add(style("Block", CombatStyleType.CRUSH, CombatStyleStance.DEFENSIVE));
				break;
			case SPIKED:
				ret.add(style("Pound", CombatStyleType.CRUSH, CombatStyleStance.ACCURATE));
				ret.add(style("Pummel", CombatStyleType.CRUSH, CombatStyleStance.AGGRESSIVE));
				ret.add(style("Spike", CombatStyleType.STAB, CombatStyleStance.CONTROLLED));
				ret.add(style("Block", CombatStyleType.CRUSH, CombatStyleStance.DEFENSIVE));
				break;
			case STAFF:
				ret.add(style("Bash", CombatStyleType.CRUSH, CombatStyleStance.ACCURATE));
				ret.add(style("Pound", CombatStyleType.CRUSH, CombatStyleStance.AGGRESSIVE));
				ret.add(style("Focus", CombatStyleType.CRUSH, CombatStyleStance.DEFENSIVE));
				ret.add(style("Spell", CombatStyleType.MAGIC, CombatStyleStance.DEFENSIVE_AUTOCAST));
				ret.add(style("Spell", CombatStyleType.MAGIC, CombatStyleStance.AUTOCAST));
				break;
			case AXE:
				ret.add(style("Chop", CombatStyleType.SLASH, CombatStyleStance.ACCURATE));
				ret.add(style("Hack", CombatStyleType.SLASH, CombatStyleStance.AGGRESSIVE));
				ret.add(style("Smash", CombatStyleType.CRUSH, CombatStyleStance.AGGRESSIVE));
				ret.add(style("Block", CombatStyleType.SLASH, CombatStyleStance.DEFENSIVE));
				break;
			case NONE:
			case UNARMED:
				ret.add(style("Punch", CombatStyleType.CRUSH, CombatStyleStance.ACCURATE));
				ret.add(style("Kick", CombatStyleType.CRUSH, CombatStyleStance.AGGRESSIVE));
				ret.add(style("Block", CombatStyleType.CRUSH, CombatStyleStance.DEFENSIVE));
				break;
			case SCYTHE:
				ret.add(style("Reap", CombatStyleType.SLASH, CombatStyleStance.ACCURATE));
				ret.add(style("Chop", CombatStyleType.SLASH, CombatStyleStance.AGGRESSIVE));
				ret.add(style("Jab", CombatStyleType.CRUSH, CombatStyleStance.AGGRESSIVE));
				ret.add(style("Block", CombatStyleType.SLASH, CombatStyleStance.DEFENSIVE));
				break;
			case SLASH_SWORD:
				ret.add(style("Chop", CombatStyleType.SLASH, CombatStyleStance.ACCURATE));
				ret.add(style("Slash", CombatStyleType.SLASH, CombatStyleStance.AGGRESSIVE));
				ret.add(style("Lunge", CombatStyleType.STAB, CombatStyleStance.CONTROLLED));
				ret.add(style("Block", CombatStyleType.SLASH, CombatStyleStance.DEFENSIVE));
				break;
			case SPEAR:
				ret.add(style("Lunge", CombatStyleType.STAB, CombatStyleStance.CONTROLLED));
				ret.add(style("Swipe", CombatStyleType.SLASH, CombatStyleStance.CONTROLLED));
				ret.add(style("Pound", CombatStyleType.CRUSH, CombatStyleStance.CONTROLLED));
				ret.add(style("Block", CombatStyleType.STAB, CombatStyleStance.DEFENSIVE));
				break;
			case STAB_SWORD:
				ret.add(style("Stab", CombatStyleType.STAB, CombatStyleStance.ACCURATE));
				ret.add(style("Lunge", CombatStyleType.STAB, CombatStyleStance.AGGRESSIVE));
				ret.add(style("Slash", CombatStyleType.SLASH, CombatStyleStance.AGGRESSIVE));
				ret.add(style("Block", CombatStyleType.STAB, CombatStyleStance.DEFENSIVE));
				break;
			case WHIP:
				ret.add(style("Flick", CombatStyleType.SLASH, CombatStyleStance.ACCURATE));
				ret.add(style("Lash", CombatStyleType.SLASH, CombatStyleStance.CONTROLLED));
				ret.add(style("Deflect", CombatStyleType.SLASH, CombatStyleStance.DEFENSIVE));
				break;
			case FLAIL:
				ret.add(style("Chop", CombatStyleType.SLASH, CombatStyleStance.ACCURATE));
				ret.add(style("Slash", CombatStyleType.SLASH, CombatStyleStance.AGGRESSIVE));
				ret.add(style("Block", CombatStyleType.SLASH, CombatStyleStance.DEFENSIVE));
				break;
			default:
				break;
		}

		// Add a pseudo combat style here for manual casting
		ret.add(style("Spell", CombatStyleType.MAGIC, CombatStyleStance.MANUAL_CAST));
		return ret;
	}

	private static PlayerCombatStyle style(String name, CombatStyleType type, CombatStyleStance stance)
	{
		return new PlayerCombatStyle(name, type, stance);
	}
}

